      "pageNumber": 3,
      "text": "ÉTAGE 0 — LE TERRAIN\nLe travail réel\nQuatre lieux. Quatre métiers. Le même lundi matin.\nLIEU 1 — Un théâtre, quelque part.\n7h45. Le parking est vide, mais pas pour longtemps. Dans deux heures,\ntrois cents personnes vont s'asseoir dans cette salle et attendre qu'on leur\nraconte une histoire. Ils ont payé pour ça. Certains ont économisé pour être\nlà.\nEn coulisses, une dizaine de personnes s'activent. Vérification lumières.\nTests son. Calage machines. Un projecteur montre des signes de faiblesse\n— on le remplace sans en parler à personne, parce que c'est le métier et\nqu'on sait faire.\nLe téléphone sonne. Le responsable ne viendra pas. Réunion au siège.\n« Réalignement stratégique des opérations », dit le mail.\nLe régisseur raccroche. Hausse les épaules. Le check continue. À 10h30, le\nspectacle commence. Il est impeccable.\nLIEU 2 — Un service hospitalier, ailleurs.\n6h50. Transmission de nuit. L'infirmière qui arrive prend les constantes,\nles traitements en cours, les alertes. Chambre 12, surveillance renforcée.\nChambre 7, perfusion à changer à 9h.\nLa cadre de santé est en formation toute la semaine. Quelque chose sur le\n« pilotage de la performance soignante ».\nL'infirmière ne lève même pas les yeux. Elle sait ce qu'elle a à faire. Elle le\nfait depuis huit ans. Les patients seront soignés, les familles seront\ninformées, les urgences seront gérées.\n2",
