      "pageNumber": 4,
      "text": "LIEU 3 — Un restaurant, en centre-ville.\n10h00. Le chef est en cuisine. Livraisons du matin : il vérifie la fraîcheur,\nrefuse un lot de poisson douteux, ajuste le menu du jour. Les commis\npréparent les mises en place. La salle est dressée.\nLe directeur régional ? Personne ne sait exactement où il est. Quelque part\nentre deux \"audits terrain\" qui ressemblent surtout à des déjeuners\nd'affaires.\nÀ midi, le service est plein. Chaque assiette sort dans les temps. Chaque\nclient repart satisfait.\nLIEU 4 — Un chantier, en banlieue.\n7h00. Le chef d'équipe distribue les tâches. Aujourd'hui, on coule la dalle\ndu deuxième étage. Le ferrailleur est en place. Le grutier attend le signal.\nLe maçon vérifie les niveaux.\nLe conducteur de travaux est en réunion avec le maître d'ouvrage. Il y\npassera la journée. Tableaux Excel, pourcentages d'avancement, marges\nprévisionnelles.\nSur le chantier, la dalle sera coulée avant 16h. Parfaitement.\nQuatre endroits. Quatre métiers. Quatre managers\nabsents.\nZéro interruption.\nPosez-vous la question. Pas pour ces gens-là. Pour vous.\nSi demain, les gens \"d'en haut\" ne viennent pas — est-ce que ça s'arrête ?\nOu est-ce que ça continue ?\nEt si ça continue...\n3",
