      "pageNumber": 5,
      "text": "Alors, qu'est-ce qu'ils font de leurs journées ?\nCe n'est pas une attaque. C'est une question. Peut-être la plus simple qu'on\npuisse poser dans le monde du travail. Et pourtant, dans la plupart des\norganisations, personne ne la pose. Ni en haut — parce qu'on n'a pas\nintérêt à y répondre. Ni en bas — parce qu'on n'a pas le droit de la poser.\nCe livre la pose.\nEt il ne s'arrêtera pas à cette question. Il ira chercher pourquoi le travail est\norganisé comme ça. Depuis quand. Au profit de qui. Et surtout — comment\nça pourrait être autrement.\nPas dans un monde utopique. Pas dans un rêve.\nDans le monde réel. Celui où vous vous levez chaque matin.\n▌  VOIX DU TERRAIN\n« Un jour, le bâtiment a été fermé pour un problème sanitaire. Personne\nne pouvait travailler. Chaque chef de service a décidé seul s'il renvoyait\nses gens chez eux ou non. Résultat : dans le même bâtiment, certaines\néquipes sont rentrées chez elles payées, d'autres sont restées à attendre,\npour rien. La seule différence ? Le manager qu'ils avaient eu la chance —\nou la malchance — d'avoir. »\n— Agent technique, secteur du divertissement\n« J'ai développé un outil sur mon temps libre pour rendre notre\nplanning lisible. L'ancien système avait vingt ans et personne en haut\nn'avait jugé utile de le changer. Mes collègues l'utilisent tous les jours.\nMa hiérarchie ne m'en a jamais parlé. Ni merci, ni bravo, ni \"arrête\".\nJuste le silence. »\n— Technicien, grande entreprise de services\n4",
