      "text": "« Quand on me confie un projet, que l'on me fait confiance, je donne\ntout. Quand on me surveille, je me demande ce que j'ai fait de mal. C'est\naussi simple que ça. »\n— Ouvrier qualifié, secteur du bâtiment\n▌  LE TRADUCTEUR\nCe qu'on dit à l'étage 9... et ce que ça veut dire à l'étage 0.\nEn haut En bas\n« Réalignement des ressources » On va virer du monde\n« Optimiser le parcours client » Faire plus avec moins de gens\n« Conduite du changement » On a décidé sans vous, adaptez-vous\n« Capital humain » Vous êtes une ligne dans un tableur\n« Montée en compétences » Formation obligatoire inutile\n« Synergie inter-services » Réunion où personne n'écoute\n« Agilité organisationnelle » On change d'avis tous les trois mois\n5",
