      "pageNumber": 7,
      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 0 — LE TERRAIN\nPopulation : ~25 000 opérateurs / techniciens (71 % des eﬀectifs)\nRémunération : la plus basse de la tour\nDistance au réel : 0 — ils SONT le réel\nImpact sur le produit : direct, immédiat, visible\nPouvoir de décision : limité à l'instant présent\nInnovations produites : nombreuses — rarement reconnues\nRemplaçabilité perçue : totale\nMotivation principale : le métier lui-même\n▌  LA QUESTION\nCe livre se lit dans les deux sens.\nSi vous êtes du terrain — ouvrez ici, montez les étages, et découvrez ce qui\nse passe au-dessus de vous. Ce que vous y trouverez ne vous surprendra\npeut-être pas. Mais le voir noir sur blanc pourrait changer votre regard.\nSi vous êtes du bureau — retournez ce livre, commencez par l'autre\ncouverture, et descendez vers le terrain. Ce que vous y trouverez pourrait\nvous surprendre. Et c'est le but.\nDans les deux cas, vous finirez au même endroit : le Hall. L'étage où tout le\nmonde se retrouve pour construire la suite.\n▌  LE SAVIEZ-VOUS ?\nEn 1911, un ingénieur américain nommé Frederick Winslow Taylor publie\nLes Principes du Management Scientifique. Son idée fondatrice est\nlimpide : séparer ceux qui pensent le travail de ceux qui l'exécutent. Les\n6",
