      "text": "premiers planifient, mesurent, contrôlent. Les seconds obéissent et\nreproduisent.\nCette idée a plus d'un siècle.\nDepuis, on a inventé internet. L'intelligence artificielle. On a envoyé des\nrobots sur Mars. On a séquencé le génome humain.\nMais la manière dont on organise le travail dans la grande majorité des\nentreprises ?\nElle n'a pas bougé d'un étage.\n▲▼ ■ □ □ □ □ □ □ □ □ ÉTAGE 0 SUR 9\nProchain étage — Le Manager de Proximité. Celui qui est juste au-dessus — parfois\njuste à côté — et qui se demande, certains matins, ce qu'il fait là.\n7",
