      "pageNumber": 9,
      "text": "ÉTAGE 1 — LE MANAGER DE PROXIMITÉ\nCelui qui est monté d'un étage — et qui ne sait plus où il\nhabite\nIl faut qu'on parle de cette personne. Parce que si ce livre tapait\nuniquement sur les managers, il serait malhonnête. Et on ne veut pas être\nmalhonnête.\nLe manager de proximité — appelez-le chef d'équipe, responsable de\nservice, cadre de santé, maître d'hôtel, chef de chantier, selon votre secteur\n— est la personne la plus tiraillée de toute la tour.\nPourquoi ?\nParce qu'en général, elle vient du terrain.\nIl y a quelques années, cette personne était à l'étage 0. Elle faisait le métier.\nElle était bonne. Peut-être la meilleure de son équipe. Et un jour, on lui a\ndit :\n« Tu es excellent. On te propose de monter. »\nMonter. Le mot est beau. Il suggère l'élévation. La reconnaissance. Le\nprogrès. Dans l'imaginaire collectif, monter c'est réussir.\nAlors elle a dit oui.\nEt elle a changé d'étage.\nCe qu'on lui a promis\nPlus de responsabilités\nUn meilleur salaire\nUne vision plus large\n8",
