      "pageNumber": 10,
      "text": "La possibilité de « faire bouger les choses »\nCe qu'elle a reçu\nDes réunions. Beaucoup de réunions.\nDes tableaux Excel à remplir pour l'étage au-dessus\nDes mails. Des centaines de mails. La plupart en copie, pour\n« traçabilité »\nUn planning à gérer avec un logiciel que personne n'a mis à jour\ndepuis quinze ans\nLe droit de dire non à ses anciens collègues\nEt une question, au fond, qu'elle n'ose poser à personne :\n« Je faisais un vrai métier. Maintenant, je fais quoi ? »\nLa journée type\nSuivons-la, cette journée. On ne va pas caricaturer. On va juste observer.\n8h00 — Arrivée. Mails. 47 non lus depuis hier soir. La moitié sont des CC.\nUn quart sont des demandes de validation. Deux sont importants. Il faut\nles retrouver dans le tas.\n8h30 — Brief d'équipe. Cinq minutes utiles. Distribuer l'information,\nrépondre aux questions, transmettre un changement de planning décidé en\nhaut. Le reste est du rituel.\n9h00 — Réunion avec l'étage 2. Point hebdomadaire. On y parle\nd'indicateurs. Taux de présence. Coûts. Heures supplémentaires. Le\nmanager de proximité traduit : il transforme le vécu de son équipe en\nchiffres que l'étage au-dessus peut comprendre. L'équipe est fatiguée\ndevient « le taux d'absentéisme a augmenté de 3 points ».\n9",
