      "text": "10h00 — Gestion administrative. Congés à valider. Plannings à ajuster. Un\narrêt maladie est tombé — il faut trouver un remplaçant. L'outil de gestion\nest lent. Les codes sont incompréhensibles. Il bricole.\n11h00 — Un problème sur le terrain. Quelque chose ne fonctionne pas. Le\nmanager descend. Il regarde. Il constate que l'équipe a déjà résolu le\nproblème sans lui. Il remonte.\n12h00 — Déjeuner. À la cantine du siège, pas avec l'équipe. Pas par choix —\npar habitude. L'étage sépare.\n14h00 — Réunion de suivi de projet. Trois personnes parlent. Sept\nécoutent. Deux regardent leur téléphone. Un PowerPoint de 42 slides est\nprojeté. L'information utile tient en 3 phrases.\n15h30 — Un conflit entre deux membres de l'équipe. Le manager écoute,\ntempère, tranche. C'est peut-être le seul moment de sa journée où il fait\nquelque chose que personne d'autre ne pourrait faire.\n16h30 — Reporting. Remplir les tableaux de l'étage 2. Traduire à nouveau.\nTrois heures de travail d'équipe deviennent trois lignes dans un fichier que\nle Manager de Managers survolera en diagonale.\n17h30 — Fin de journée. Le manager part avec le sentiment confus d'avoir\nété occupé toute la journée sans avoir rien fait de vraiment utile.\nEt demain, on recommence.\nLe piège\nVoici le piège dans lequel le manager de proximité est enfermé, souvent\nsans le savoir :\nIl ne fait plus le métier — il l'administre. Or personne ne lui a appris à\nadministrer. On lui a appris à faire. Il était électricien, infirmier, cuisinier,\nmaçon, technicien — et maintenant il est gestionnaire. Un métier\nentièrement différent, pour lequel il n'a reçu, au mieux, qu'une formation\n10",
