      "text": "de deux jours sur « le leadership » et un mot de passe pour un logiciel de\nplanning.\nEt le système ne voit pas le problème. Parce que dans la logique de la tour :\nÊtre bon en bas = être prêt à monter.\nC'est faux. Être un excellent chirurgien ne fait pas de vous un bon chef de\nservice. Être un cuisinier extraordinaire ne fait pas de vous un bon\ndirecteur de restaurant. Être le meilleur technicien lumière ne fait pas de\nvous un bon responsable d'équipe.\nCe sont des métiers différents. Mais la tour ne connaît qu'une seule\ndirection : vers le haut.\nLa loterie\nEt puis il y a l'autre vérité, celle que tout le monde connaît à l'étage 0 mais\nque personne n'écrit :\nTous les managers de proximité ne sont pas là pour les mêmes raisons.\nCertains sont montés parce qu'ils étaient bons ET qu'ils avaient envie de\ntransmettre, d'organiser, de protéger leur équipe. Ceux-là font souvent un\ntravail remarquable — et rarement reconnu.\nD'autres sont montés parce qu'ils étaient au bon endroit au bon moment.\nParce qu'ils connaissaient les bonnes personnes. Parce qu'ils ne faisaient\npas de vagues. Parce qu'ils ressemblaient à ceux qui les ont choisis.\nL'étage 0 le sait. L'étage 0 fait la différence immédiatement entre un\nmanager qui protège et un manager qui se protège. Mais l'étage 0 n'a\naucun pouvoir dans ce choix.\nC'est une loterie. Votre qualité de vie au travail — votre planning, vos\ncongés, votre droit à l'erreur, votre droit de parole — dépend largement\n11",
