      "pageNumber": 13,
      "text": "d'une personne que vous n'avez pas choisie, qui n'a pas été formée pour ce\nrôle, et qui peut être remplacée demain par quelqu'un de radicalement\ndifférent.\nDans quel autre domaine de la vie accepterait-on une telle loterie ?\nLa lente métamorphose\nLe plus troublant, c'est ce qui arrive au fil du temps.\nLe manager de proximité, au début, se souvient du terrain. Il parle encore\nla même langue. Il comprend les frustrations. Il se bat parfois pour son\néquipe face à l'étage au-dessus.\nEt puis les mois passent. Les années.\nIl passe de plus en plus de temps en réunion et de moins en moins de\ntemps sur le terrain. Son vocabulaire change. Il commence à dire « on doit\nêtre agiles » et « il faut prioriser ». Il défend des décisions qu'il n'a pas\nprises, parce que c'est son rôle. Il transmet des consignes auxquelles il ne\ncroit pas, parce que c'est attendu de lui.\nUn jour, quelqu'un de l'étage 0 lui fait remarquer : « Tu as changé. »\nIl ne le voit pas. Ou il ne veut pas le voir. Parce que le voir, ce serait\nadmettre que monter d'un étage, ce n'est pas grandir.\nC'est juste changer de camp.\n12",
