      "text": "▌  VOIX DU TERRAIN\n« Mon ancien chef d'équipe, quand il était avec nous, c'était le meilleur.\nIl comprenait tout, il anticipait, il avait les solutions avant qu'on ait les\nproblèmes. Depuis qu'il est \"monté\", il passe ses journées en réunion.\nL'autre jour, il nous a envoyé un mail pour nous dire ce qu'on savait\ndéjà. Je me suis dit : c'est ça, maintenant, son métier ? »\n— Technicienne, secteur du spectacle vivant\n« J'ai refusé le poste de cadre de santé trois fois. On me dit que je\n\"plafonne\". Mais moi, je suis infirmière. C'est ça, mon métier. Pourquoi\n\"réussir\" devrait vouloir dire \"arrêter de soigner\" ? »\n— Infirmière, hôpital public, 15 ans d'ancienneté\n« Quand j'étais en cuisine, je créais. Maintenant, je remplis des tableurs.\nMa femme me demande parfois : \"Mais concrètement, tu as fait quoi\naujourd'hui ?\" Honnêtement, certains soirs, je ne sais pas quoi\nrépondre. »\n— Ancien chef cuisinier, devenu responsable de restauration\n13",
