      "text": "▌  LA QUESTION\nSi vous êtes manager de proximité, répondez honnêtement :\nQuelle part de votre journée est réellement utile à votre équipe ?\nPas utile au reporting. Pas utile à votre hiérarchie. Utile à votre équipe.\nÀ ceux qui font.\nSi la réponse vous met mal à l'aise — c'est que vous avez compris le\nproblème.\nEt si vous êtes du terrain : votre manager de proximité n'est pas votre\nennemi. Il est, souvent, la première victime du système — celle qu'on a\npromue pour mieux l'enfermer.\n▌  LE SAVIEZ-VOUS ?\nEn 1969, un professeur canadien nommé Laurence J. Peter publie un livre\nau titre provocateur : Le Principe de Peter. Sa thèse tient en une phrase :\n« Dans une hiérarchie, tout employé tend à s'élever à son niveau\nd'incompétence. »\nAutrement dit : on vous promeut parce que vous êtes bon à votre poste.\nPuis encore. Puis encore. Jusqu'à ce que vous arriviez à un poste où vous\nn'êtes plus bon — et là, vous y restez. Parce que dans la tour, on ne\nredescend pas. Redescendre, c'est échouer.\nCinquante-sept ans plus tard, dans des millions de bureaux à travers le\nmonde, le Principe de Peter fonctionne toujours à plein régime.\nLa seule chose qui a changé, c'est qu'aujourd'hui, les gens d'en bas le\nvoient.\n15",
