      "text": "ÉTAGE 2 — LE RESPONSABLE DE\nSERVICE\nCelui qui ne connaît plus les prénoms\nÀ l'étage 1, le manager connaît encore son équipe. Il sait que Thomas a un\nenfant malade, que Sophie veut changer de poste, que le projecteur du fond\na un faux contact depuis trois semaines. Il a le visage des gens en tête,\nmême quand il remplit ses tableaux.\nÀ l'étage 2, les visages disparaissent.\nCe n'est pas de la cruauté. C'est de l'arithmétique.\nLe mur du nombre\nQuand vous gérez 10 personnes, vous connaissez leurs prénoms, leurs\nforces, leurs faiblesses, leurs enfants, leur humour.\nQuand vous gérez 70 personnes à travers des managers qui eux-mêmes\ngèrent des équipes, vous connaissez... des chiffres.\nQuand vous en gérez 350, vous ne connaissez même plus les chiffres par\ncœur. Vous avez un dashboard.\nLe Manager de Managers vit dans un monde de dashboards.\nLa journée vue d'en haut\n8h00 — Arrivée au bureau. Un vrai bureau, cette fois. Avec une porte.\nParfois une vitre. Parfois un étage différent de celui de ses équipes. Le\nmobilier est meilleur. Le café aussi.\n8h15 — Mails. Pas 47 comme à l'étage 1 — mais 120. La moitié viennent de\nl'étage 3. Un quart sont des invitations à des réunions. Le reste sont des\n17",
