      "pageNumber": 23,
      "text": "de ses journées à nourrir les fonctions support en données, formulaires et\njustifications.\nSur le Terrain, cela se traduit par :\nL'inflation des indicateurs de performance (KPI, pour Key\nPerformance Indicators) : ces chiffres d'objectifs chiffrés créés par le\nsiège pour mesurer à distance la productivité. Le technicien ou\nl'infirmière ne fait plus seulement son métier; il doit cocher 40 cases\npar jour sur une tablette pour prouver qu'il l'a fait.\nLes outils imposés sans consultation  : L'adoption d'un nouveau\nlogiciel RH ou d'un outil de ticketing conçu par un siège parisien ou\nlondonien, inutilisable en conditions réelles d'exploitation.\nLa neutralisation de l'initiative : Impossible de faire réparer une\nmachine ou d'acheter une fourniture à 50 euros sans passer par 3\nvalidations de la comptabilité et des achats.\nLe Traducteur Corporate : « Nous déployons un nouvel outil transverse\nd'harmonisation de l'expérience collaborateur. » — Traduction Terrain :\n« Vous allez perdre 45 minutes par jour à remplir des formulaires\nbuggés pour qu'un consultant puisse faire des graphiques colorés au\n6ème étage. »\n▌  VOIX DU TERRAIN\n« Quand notre Manager de Managers vient sur le terrain — ça arrive\nune fois par trimestre peut-être — tout le monde se tend. Pas parce qu'on\na peur. Parce qu'on sait qu'il ne comprend plus. Il regarde, il hoche la\ntête, il dit \"c'est bien\". Mais il ne voit pas ce qu'on voit. Il ne sent pas ce\nqu'on sent. Il visite. On vit. »\n— Chef de rang, chaîne de restauration\n22",
