      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 2 — LE RESPONSABLE DE SERVICE\nPopulation : ~500 managers de proximité (~50 personnes sous responsabilité)\nRémunération : x2 à x3 vs. terrain\nDistance au réel : mesurée en dashboards\nImpact sur le produit : aucun au quotidien\nPouvoir de décision : réel mais contraint par l'étage 3\nProduit principal : réorganisations et reportings\n• Temps sur le terrain : quasi nul\nMotivation : pouvoir, statut, survie politique\nConnaissance du terrain : abstraite\n▌  LA QUESTION\nSi vous êtes Manager de Managers, répondez honnêtement :\nÀ quand remonte la dernière fois où vous avez passé une journée entière\nsur le terrain ?\nPas une visite de courtoisie. Pas un tour rapide pour serrer des mains.\nUne journée entière — arrivée à l'heure de l'équipe, départ à l'heure de\nl'équipe, les mains dans le réel.\nSi ça remonte à plus de six mois, vous ne gérez plus une réalité.\nVous gérez une idée de la réalité.\n24",
