      "pageNumber": 26,
      "text": "▌  LE SAVIEZ-VOUS ?\nEn 2018, l'anthropologue américain David Graeber publie Bullshit Jobs. Il\ny décrit des millions d'emplois qui, selon ceux-là mêmes qui les occupent,\nn'ont aucune utilité réelle. Pas des emplois mal payés ou ingrats — non, des\nemplois bien payés, confortables, et profondément vides de sens.\nGraeber identifie cinq catégories de bullshit jobs. L'une d'elles s'appelle les\n« task makers » — ceux dont le rôle principal est de créer du travail pour\nles autres. Organiser des réunions. Lancer des projets. Commander des\naudits. Restructurer des départements.\nPas parce que c'est nécessaire.\nParce que c'est leur manière de justifier l'étage qu'ils occupent.\n▲▼ ■ ■ ■ □ □ □ □ □ □ ÉTAGE 2 SUR 9\nProchain étage — Le Directeur. Celui qui ne voit plus le produit — il voit\nl'organigramme.\n25",
