      "pageNumber": 27,
      "text": "ÉTAGE 3 — LE DIRECTEUR\nCelui qui ne voit plus le produit — il voit l'organigramme\nÀ l'étage 0, on fabrique quelque chose. Un spectacle. Un soin. Un repas. Un\nmur.\nÀ l'étage 1, on organise ceux qui fabriquent.\nÀ l'étage 2, on organise ceux qui organisent.\nÀ l'étage 3, on ne sait plus très bien ce qu'on organise. Mais on a un budget\npour le faire.\nL'organigramme comme territoire\nSi vous entrez dans le bureau d'un Directeur — et c'est un vrai bureau, cette\nfois, avec une porte fermée, une table de réunion intégrée, et parfois une\nvue — vous trouverez, affiché quelque part ou ouvert sur son écran,\nl'organigramme.\nL'organigramme est la carte de son monde. Pas le plan du théâtre. Pas le\nplan de l'hôpital. Pas le plan du chantier. L'organigramme. Des cases\nreliées par des lignes. Chaque case porte un nom de service et un chiffre : le\nnombre de personnes.\nLe Directeur passe une partie significative de son temps à modifier cette\ncarte. Fusionner deux cases. En séparer une. Créer une nouvelle ligne de\nrattachement. Supprimer un niveau. En ajouter un.\nL'étage 0 ne verra jamais cette carte. L'étage 0 verra les conséquences : un\nmatin, un mail annonce qu'ils changent de département. Que leur manager\na changé. Que leur service s'appelle autrement. Que tout est « exactement\npareil, mais en mieux ».\n26",
