      "text": "L'étage 0 retournera faire le spectacle. Le même spectacle. Avec les mêmes\nmains. Dans le même théâtre.\nSeule la case a bougé.\nLe langage de l'argent\nÀ l'étage 3, une mutation linguistique s'achève. Le Directeur ne parle plus\ndu tout la langue du terrain. Il ne parle même plus tout à fait celle de\nl'étage 2. Il parle la langue de l'argent.\nTout est converti en euros.\nCe que c'est Ce que le Directeur voit\nUne équipe de 12 techniciens 480 000 € de masse salariale\nUn spectacle de 45 minutes Un coût d'exploitation par représentation\nUn arrêt maladie Un taux à optimiser\nUne idée d'amélioration Un ROI à calculer\nUn être humain Un ETP (Équivalent Temps Plein)\nETP. Trois lettres qui résument tout. Vous n'êtes pas une personne. Vous\nêtes un Équivalent Temps Plein. Une unité de mesure. Un nombre décimal.\nOn peut avoir 11,5 ETP dans un service — c'est-à-dire onze personnes et\ndemie. Quelqu'un, quelque part, est une demi-personne dans un tableur.\nEt le Directeur ne trouve pas ça choquant. Pas par cruauté. Par habitude.\nParce que c'est la langue qu'on parle à cet étage. Et que pour être compris à\nl'étage 4, il faut parler cette langue-là.\n27",
