      "pageNumber": 30,
      "text": "Pourquoi une entreprise paie-t-elle des centaines de milliers d'euros à\ndes gens de l'extérieur pour apprendre ce que ses propres employés\npourraient lui dire gratuitement ?\nLa réponse est simple et terrible : parce que la tour n'a pas de mécanisme\npour écouter le bas.\nL'information du terrain ne monte pas. Elle est filtrée à chaque étage,\ntraduite, résumée, déformée. Ce qui arrive à l'étage 3, c'est un écho lointain\ndu réel. Alors le Directeur fait appel à quelqu'un de l'extérieur pour aller\nvoir ce qui se passe à l'intérieur de sa propre organisation.\nC'est comme si le capitaine d'un navire engageait un plongeur pour aller\nvoir si la coque prend l'eau — alors qu'il suffirait de demander aux marins\ndans la cale.\nMais les marins dans la cale, personne ne leur demande.\nLa stratégie comme horizon\nLe Directeur a un autre outil que les étages inférieurs n'ont pas : le plan\nstratégique.\nLe plan stratégique est un document qui décrit ce que l'organisation sera\ndans trois à cinq ans. Il contient des « axes », des « ambitions », des\n« piliers ». Il est illustré de flèches convergentes, de cercles concentriques,\net de mots comme « excellence », « innovation », « centricité client ».\nL'étage 0 n'a jamais vu ce document. Ou s'il l'a vu, il n'a pas compris. Pas\npar manque d'intelligence — par manque de connexion. Le plan\nstratégique parle d'un monde abstrait. L'étage 0 vit dans un monde\nconcret.\nEt voici le paradoxe :\n29",
