      "pageNumber": 31,
      "text": "Le plan stratégique change tous les deux ans. Le travail réel, lui, ne\nchange presque pas.\nLes spectacles sont les mêmes. Les soins sont les mêmes. Le service est le\nmême. Le béton est le même. Le plan dit « transformation digitale » et\n« expérience client réinventée », mais en bas, les gens font le même geste,\navec les mêmes outils, dans les mêmes conditions.\nLe plan stratégique est une fiction confortable — une histoire que la tour se\nraconte pour donner un sens à son existence.\nLa cage dorée\nLe Directeur gagne bien sa vie. Très bien, même. Son salaire est un\nmultiple de celui du terrain — trois, quatre, cinq fois plus, parfois\ndavantage. Il a des avantages  : voiture de fonction, assurance\ncomplémentaire premium, accès à des séminaires dans des lieux agréables,\nbonus annuels indexés sur des indicateurs qu'il a lui-même contribué à\ndéfinir.\nEt pourtant.\nLe Directeur est, à sa manière, coincé.\nIl ne peut pas redescendre — ce serait un aveu d'échec.\nIl ne peut pas monter facilement — les places à l'étage 4 sont rares et\nla compétition est féroce.\nIl ne peut pas parler franchement — à l'étage 4, on attend de la\nconformité, pas de la contestation.\nIl ne peut pas changer le système — il est le système.\nCertains Directeurs en ont conscience. Le soir, dans leur voiture de\nfonction, entre le bureau et la maison, il y a un moment de silence où la\nquestion affleure :\n30",
