      "text": "Est-ce que c'est vraiment ça que je voulais faire de ma vie ?\nLe feu passe au vert. La question s'efface. Demain, il y a comité stratégique.\n▌  VOIX DU TERRAIN\n« Un cabinet de conseil est venu nous observer pendant deux semaines.\nIls m'ont posé des questions pendant vingt minutes. Six mois plus tard,\nun document de 150 pages est sorti. Les conclusions, c'était exactement\nce qu'on avait dit en délégation syndicale trois ans avant. Sauf que nous,\non était gratuits. »\n— Aide-soignante, hôpital public\n« Notre Directeur est venu au dernier spectacle de la saison. Il a dit que\nc'était \"formidable\". Il ne savait pas que c'était le même spectacle que\ncelui qu'il avait vu il y a deux ans. Le même. Note pour note. Geste pour\ngeste. Il ne voit pas le show. Il voit l'événement. »\n— Régisseur, arts vivants\n« Ils nous ont présenté le \"plan stratégique 2025-2028\". Quatre piliers :\nExcellence, Innovation, Durabilité, Centricité Client. Je suis allé vérifier.\nLe plan précédent avait quatre piliers aussi : Performance, Innovation,\nResponsabilité, Orientation Client. C'est les mêmes mots dans un ordre\ndifférent. »\n— Développeur senior, groupe technologique\n31",
