      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 3 — LE DIRECTEUR\nPopulation : ~120 directeurs de site / chefs de service (~300 personnes)\nRémunération : x3 à x5 vs. terrain\nDistance au réel : mesurée en plans stratégiques\nImpact sur le produit : nul au quotidien, fort par\ndécisions structurelles\nPouvoir de décision : réel mais orienté budget\nProduit principal : organigrammes et stratégies\n• Dernière visite terrain : il y a longtemps\nOutil préféré : le cabinet de conseil\nMotivation : impact (perçu), statut, carrière\nPiège : ne peut plus redescendre\n▌  LA QUESTION\nSi vous êtes Directeur, répondez honnêtement :\nPourriez-vous décrire, en détail, le travail quotidien d'une personne à\nl'étage 0 de votre organisation ?\nPas les grandes lignes. Le détail. L'heure d'arrivée. Le premier geste. La\ndifficulté récurrente. Le moment de fierté. Le moment d'épuisement. Le\ntrajet retour.\nSi vous ne pouvez pas — demandez-vous comment vous pouvez diriger\nce que vous ne connaissez pas.\n33",
