      "text": "▌  LE SAVIEZ-VOUS ?\nEn 2013, un ancien trader devenu chercheur en management, Isaac Getz,\npublie Liberté & Cie. Il y raconte l'histoire d'entreprises qui ont supprimé\nles étages intermédiaires et donné l'autonomie aux équipes terrain. FAVI,\nune fonderie picarde, fonctionne sans organigramme, sans service des\nméthodes, sans pointeuse — et elle est leader européen de son marché.\nSon patron de l'époque, Jean-François Zobrist, résume sa philosophie en\nune phrase :\n« L'homme est bon. Il faut lui faire confiance. »\nÀ l'étage 3, cette phrase fait sourire. Ou inquiète.\nÀ l'étage 0, elle semble évidente.\n▲▼ ■ ■ ■ ■ □ □ □ □ □ ÉTAGE 3 SUR 9\nProchain étage — Le Vice-Président. Celui qui ne voit plus l'entreprise — il voit le\nmarché.\n34",
