      "pageNumber": 36,
      "text": "ÉTAGE 4 — LE VICE-PRÉSIDENT\nCelui qui ne voit plus l'entreprise — il voit le marché\nIl y a un moment, dans l'ascension de la tour, où quelque chose bascule\ndéfinitivement. Ce n'est pas progressif. C'est un seuil. On le franchit sans\ns'en rendre compte, et après, on ne revient plus.\nCe seuil est à l'étage 4.\nLe Vice-Président (souvent désigné sous le sigle VP dans les grandes\nentreprises et multinationales) ne regarde plus à l'intérieur de la tour. Il\nregarde par la fenêtre.\nDehors, il y a le marché. Les concurrents. Les actionnaires. Les analystes\nfinanciers. Les tendances du secteur. Les conférences internationales. C'est\nça, son monde. L'intérieur — les étages en dessous, les gens, le produit —\nc'est de la plomberie. Importante, certes. Mais pas son sujet.\nSon sujet, c'est le chiffre.\nLe mal d'altitude\nEn alpinisme, au-delà d'une certaine altitude, le corps humain commence à\ndysfonctionner. L'oxygène se raréfie. La perception se trouble. On prend\ndes décisions aberrantes en croyant raisonner clairement. On appelle ça le\nmal d'altitude.\nIl existe un équivalent managérial.\nÀ l'étage 4, la distance avec le terrain est si grande que les décisions\nperdent toute texture humaine. Ce n'est pas de la méchanceté. C'est de la\nphysique. À cette altitude, un être humain devient un point sur un\ngraphique. Un service devient une ligne budgétaire. Un métier devient un\n« centre de coût ».\n35",
