      "text": "Et quand le VP décide de « réduire les coûts de 8 % », il ne voit pas ce que\nça signifie en bas.\nIl ne voit pas la réunion à l'étage 1 où le manager de proximité essaie de\nchoisir qui ne sera pas renouvelé. Il ne voit pas le technicien qui apprend\npar mail que son CDD s'arrête. Il ne voit pas les équipes restantes qui\nabsorbent la charge en silence, jusqu'à l'épuisement.\nIl voit un graphique où la courbe des coûts descend.\nEt le graphique est satisfaisant.\nDeux mondes, même semaine\nSuivons une semaine type. Pas pour caricaturer — pour comparer.\nLa semaine du VP\nJour Activité\nLundi Vol Paris — Siège international. Business class. Taxi à l'arrivée.\nComité exécutif dans une salle avec vue panoramique, café servi,\ndéjeuner traiteur.\nMardi Présentation aux investisseurs. Slides sur la « trajectoire de\ncroissance rentable ». Questions sur les marges. Dîner avec des\nhomologues dans un restaurant étoilé.\nMercredi Retour. Call de 2h avec les Directeurs (étage 3). Revue budgétaire.\nLe mot « headcount » est prononcé quatorze fois.\nJeudi Conférence sectorielle dans un grand hôtel. Panel sur « L'avenir du\ntravail ». Ironie non détectée.\nVendredi Bureau. Validation du plan de réduction des effectifs. Signature. Un\nstylo sur un document. 47 vies basculées. Puis week-end.\n36",
