      "pageNumber": 38,
      "text": "La même semaine, à l'étage 0\nJour Activité\nLundi Arrivée 7h45. Check technique. Premier show à 10h30. Il fait 36°C\nen coulisses. La clim du local technique est en panne depuis deux\nsemaines — la demande de réparation est « en cours de\ntraitement ». Trois shows. Fin à 19h.\nMardi Idem. Le collègue absent n'est pas remplacé. On fait à deux le\ntravail de trois. Personne ne se plaint — à qui ?\nMercredi Idem. Un mail de la direction annonce une « évolution\norganisationnelle ». Personne ne comprend ce que ça signifie\nconcrètement. On fait le show.\nJeudi Idem. La rumeur circule : des postes vont être supprimés. Pas de\nconfirmation officielle. L'anxiété s'installe. On fait le show.\nVendredi Idem. Un CDD apprend qu'il ne sera pas renouvelé. Il fait son\ndernier show. Le public applaudit. Il applaudit quelqu'un qui vient\nde perdre son emploi. Il ne le sait pas. Le VP non plus.\nLa compensation variable\nVoici un mécanisme que l'étage 0 ignore souvent et qui explique beaucoup\nde choses :\nLe VP a un salaire fixe — élevé. Mais il a surtout un variable. Un bonus.\nParfois des stock-options. Et ce variable est indexé sur des indicateurs\nfinanciers :\nMarge opérationnelle\nRéduction des coûts\nEBITDA (bénéfice avant intérêts, impôts, dépréciation et\namortissement — un mot que l'étage 0 n'a jamais entendu)\n37",
