      "pageNumber": 40,
      "text": "« On doit réduire le headcount de 5 %. »\n5 % de 2 100 = 105 personnes.\n105 personnes décidées en une phrase, dans une salle climatisée, sur un\nslide PowerPoint, entre le déjeuner traiteur et le café.\nLe VP qui prend cette décision n'est pas un monstre. Il ne jubile pas. Peut-\nêtre même qu'il est mal à l'aise. Mais le système dans lequel il opère ne lui\ndemande pas d'être à l'aise. Il lui demande de délivrer les chiffres. Et les\nchiffres sont clairs : moins de headcount = plus de marge = meilleur bonus\n= meilleure évaluation = maintien à l'étage 4.\nLa mécanique est implacable.\nL'avenir du travail vu d'en haut\nEt puis il y a cette scène que vous avez peut-être remarquée dans la\nsemaine du VP :\nJeudi. Conférence sectorielle. Panel sur \"L'avenir du travail\".\nC'est réel. Ça existe. Des VP et des dirigeants, assis sur une scène devant un\npublic de VP et de dirigeants, discutent de l'avenir du travail. Ils parlent de\nflexibilité, de bien-être, de sens, d'autonomie. Ils citent des études. Ils\nmontrent des slides. Ils utilisent les mots que les gens de l'étage 0 utilisent\ndans leurs conversations de vestiaire.\nEt puis ils rentrent au bureau et signent un plan de réduction d'effectifs.\nCe n'est pas de l'hypocrisie. Pas toujours. C'est pire.\nC'est de la dissociation. La capacité à penser une chose et à faire l'inverse,\nsans voir la contradiction. Parce que dans la tête du VP, « l'avenir du\ntravail » est un concept intéressant — mais le budget trimestriel est une\nréalité. Et entre un concept et un budget, le budget gagne. Toujours.\n39",
