      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 4 — LE VICE-PRÉSIDENT\nPopulation gérée : ~25 VPs / directeurs régionaux (~1 400 personnes gérées)\nRémunération : x5 à x15 vs. terrain\n(ﬁxe + variable + stock-options)\nDistance au réel : mesurée en fuseaux horaires\nImpact sur le produit : nul — impact sur la structure\nPouvoir de décision : considérable\nProduit principal : arbitrages budgétaires\n• Temps passé en avion : signiﬁcatif\nInterlocuteurs : autres VP, investisseurs, board\nMotivation : performance ﬁnancière, carrière\n  Température bureau : 22°C constants\n  Température terrain : variable (parfois 42°C)\n▌  LA QUESTION\nSi vous êtes Vice-Président, répondez honnêtement :\nLa dernière fois que vous avez pris une décision qui a supprimé des\npostes — avez-vous rencontré une seule des personnes concernées ?\nPas leur manager. Pas leur fiche. Eux. Leur visage.\nEt si la réponse est non — peut-on appeler ça une décision humaine ?\n42",
