      "text": "▌  LE SAVIEZ-VOUS ?\nEn 1961, le psychologue Stanley Milgram mène une expérience devenue\ncélèbre. Il démontre que des individus ordinaires sont capables d'infliger\nde la souffrance à d'autres à condition qu'une autorité leur dise de le faire\net qu'ils soient suffisamment éloignés de la personne qui souffre.\nLa distance, dans l'expérience de Milgram, était physique — un mur entre\nle sujet et la victime.\nDans la tour, la distance n'est pas un mur.\nC'est quatre étages.\n▲▼ ■ ■ ■ ■ ■ □ □ □ □ ÉTAGE 4 SUR 9\nProchain étage — Le Président de Division. Celui qui est l'entreprise — ou qui croit\nl'être.\n43",
