      "text": "ÉTAGE 5 — LE PRÉSIDENT DE DIVISION\nLe Town Hall et la communication\nÀ partir de cet étage, quelque chose change dans la nature même du rôle.\nLes étages 1 à 4 gèrent des gens. Avec plus ou moins de distance, plus ou\nmoins d'humanité, mais ils gèrent des gens. Ils connaissent au moins le\nnombre de services sous leur responsabilité. Ils peuvent nommer les\nDirecteurs. Ils ont un lien, même ténu, avec l'organisation vivante.\nÀ l'étage 5, on ne gère plus des gens.\nOn gère une population.\nLe maire d'une ville qui n'existe pas\n17 000 personnes. C'est le périmètre typique d'un Président de division\ndans un grand groupe. 17 000 personnes, c'est une ville. Une petite ville\nfrançaise, avec ses rues, ses quartiers, ses habitants, ses commerces, ses\nproblèmes, ses joies.\nSauf que le Président de division ne connaît pas les rues de sa ville. Il n'y\nhabite pas. Il la survole.\nLe maire d'une vraie ville de 17 000 habitants croise ses administrés au\nmarché, à la boulangerie, à la fête du village. Il voit les trottoirs cassés. Il\nsent la colère quand la piscine municipale ferme. Il reçoit les plaintes\ndirectement, en face, parfois dans la rue.\nLe Président de division, lui, vit dans un bureau au dernier étage d'un\nbâtiment administratif. Entre lui et ses 17 000 personnes, il y a :\nUn VP\nDes Directeurs\n44",
