      "pageNumber": 46,
      "text": "Des Manager de Managers\nDes Managers de proximité\nUn service de communication interne\nUn service RH\nUn secrétariat qui filtre les mails et les appels\nIl est le maire d'une ville qu'il visite en voiture officielle.\nLa communication descendante\nC'est à l'étage 5 que la communication interne prend une place centrale.\nParce que quand on ne peut pas parler à 17 000 personnes, on leur écrit.\nLa newsletter interne. Le message vidéo trimestriel. L'intranet. Les affiches\ndans les couloirs. Le mot du Président dans le journal d'entreprise.\nLe contenu est toujours le même. Décodons :\n« Chers collaborateurs, l'année écoulée a été riche en défis... »\nTraduction : ça a été difficile.\n«...que vous avez su relever avec un engagement remarquable. »\nTraduction : vous avez encaissé sans trop vous plaindre.\n« Ensemble, nous avons démontré notre résilience... »\nTraduction : on vous a demandé de faire plus avec moins, et vous l'avez\nfait.\n45",
