      "pageNumber": 48,
      "text": "Le Président arrive sur scène. Il est souriant. Détendu. Il porte une\nchemise sans cravate — pour montrer qu'il est « proche ».\nIl parle de la « formidable énergie » des équipes. Des résultats. Des\nprojets. Du futur.\nIl montre un graphique qui monte. Tout monte. Les chiffres\nmontent. La satisfaction client monte. L'engagement monte.\nPuis viennent les questions.\nLes questions :\n« Comment comptez-vous améliorer la qualité de vie au travail ? »\nRéponse calibrée de 3 minutes sur les « initiatives en cours », les « groupes\nde travail », les « axes d'amélioration identifiés ». Rien de concret.\n« Pourquoi les salaires n'augmentent-ils pas alors que les bénéfices\naugmentent ? »\nRéponse calibrée de 3 minutes sur «  le contexte économique  », la\n«  nécessité de rester compétitifs  », et la «  politique de rémunération\nglobale  » qui inclut «  les avantages sociaux qu'on oublie parfois de\ncomptabiliser ».\nLa vraie question — celle que tout le monde a en tête, celle qui brûle dans\nle ventre de l'étage 0 — n'est jamais posée. Parce qu'elle n'est pas polie.\nParce qu'on a peur. Parce que la poser, ce serait briser le spectacle.\nEt le Président de division sait mettre en scène un spectacle. Ironiquement,\ndans certains cas, c'est le seul spectacle de la maison dont il est le metteur\nen scène.\n47",
