      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 5 — LE PRÉSIDENT DE DIVISION\nPopulation gérée : ~6 présidents de division (~5 800 personnes par division)\nRémunération : x10 à x20 vs. terrain\nDistance au réel : absolue\nImpact sur le produit : aucun — impact sur l'image\nInterlocuteurs : élus, presse, actionnaires\nProduit principal : discours et décisions macro\n• Présence terrain : cérémonielle, photographiée\nVisites sur site : orchestrées par la communication\nOutil préféré : la newsletter interne\nMotivation : héritage, pouvoir, image\nConfusion : pense être l'entreprise\n▌  LA QUESTION\nSi vous êtes Président de division, répondez honnêtement :\nQuand vous dites \"nous\" — de qui parlez-vous, vraiment ?\nFermez les yeux. Visualisez les visages de votre \"nous\". Combien en\nvoyez-vous ? Dix ? Vingt ? Ceux du comité de direction, probablement.\nCeux de votre assistant(e), sûrement.\nEt les 16 980 autres ?\nVotre \"nous\" est un mot. Pas une réalité.\n51",
