      "pageNumber": 53,
      "text": "▌  LE SAVIEZ-VOUS ?\nEn 1895, le psychologue français Gustave Le Bon publie Psychologie des\nfoules. Il y décrit comment un leader peut créer un sentiment d'unité dans\nun groupe de milliers de personnes — non pas par la raison, mais par la\nrépétition, l'image et l'émotion.\nLe Town Hall, la newsletter, le message vidéo, le \"nous\" : ce sont les outils\ndécrits par Le Bon il y a 130 ans. Pas des outils de communication. Des\noutils de cohésion artificielle.\nLe leader ne rassemble pas parce qu'il connaît. Il rassemble parce qu'il\nperforme. Il joue un rôle. Sur une scène. Devant un public.\nÀ l'étage 5, le Président est un acteur.\nLa différence avec les acteurs de l'étage 0, c'est que lui, il ne le sait pas.\n▲▼ ■ ■ ■ ■ ■ ■ □ □ □ ÉTAGE 5 SUR 9\nProchain étage — Le Président International. Celui pour qui les pays sont des lignes\ndans un tableau.\n52",
