      "pageNumber": 54,
      "text": "ÉTAGE 6 — LE PRÉSIDENT\nINTERNATIONAL\nCelui pour qui les pays sont des lignes dans un tableau\nCe chapitre est plus court que les précédents. C'est intentionnel. Plus on\nmonte dans la tour, moins il y a de choses à dire sur le travail réel — parce\nqu'il n'y a plus de travail réel. Il y a du pouvoir, de la stratégie, et du\nsilence.\nÀ l'étage 6, les frontières disparaissent. Pas celles entre les gens — celles-là\nn'ont jamais été aussi grandes. Les frontières géographiques.\nLe Président International gère plusieurs pays. Chaque pays est une ligne\ndans un tableur. Chaque ligne contient un chiffre d'affaires, une marge, un\nheadcount, un potentiel de croissance. La France n'est pas un pays avec des\ngens, une culture, des syndicats, un droit du travail et des ronds-points. La\nFrance est un marché avec un P&L (Profit and Loss — compte de résultat).\nSon agenda :\nLundi : call Japon (6h du matin, décalage horaire). Mardi : vol vers le\nsiège mondial. Mercredi : board review, présentation des résultats\nrégionaux. Jeudi : dîner avec un ministre du commerce d'un pays dont il\nne parle pas la langue. Vendredi : call Europe, puis avion retour.\nDans cette semaine, pas un seul contact avec quelqu'un qui fabrique le\nproduit. Pas un. Le produit — le spectacle, le soin, le repas, le bâtiment —\nest devenu une catégorie comptable.\n53",
