      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 6 — LE PRÉSIDENT INTERNATIONAL\nPopulation gérée : ~2 présidents internationaux (~17 500 personnes / zone)\nRémunération : x15 à x30 vs. terrain\nDistance au réel : mesurée en fuseaux horaires\nContact avec le produit : inexistant\nLangue parlée : anglais corporate\nLes pays sont : des lignes P&L\nLes cultures sont : des frictions à harmoniser\nNombre de vols/an : triple chiﬀres\nMotivation : héritage historique, pouvoir global\n▌  VOIX DU TERRAIN\n« On vient d'apprendre qu'un vice-président mondial passe une journée\ndans notre parc. Tour guidée, petits fours, photo avec les équipes. Sur le\nplanning interne, c'était noté \"visite terrain\". Il est resté trois heures. Il a\nserré des mains. Il est reparti. Le lendemain, on a reçu un mail qui nous\ndemandait de \"challenger nos process d'accueil\". Apparemment, les\ntoilettes des loges VIP n'étaient pas assez propres. »\n— Technicien de spectacle, 11 ans d'ancienneté\n55",
