      "pageNumber": 59,
      "text": "ÉTAGE 7 — LE CHAIRMAN\nCelui pour qui 100 000 personnes sont un portefeuille\nCe chapitre est encore plus court. Parce qu'à cet étage, il ne se passe\npresque plus rien qui concerne le travail tel que le comprend un être\nhumain normal.\nLe Chairman — le Président du conseil, le patron de la branche globale —\nsupervise plus de 100 000 personnes. Cent mille.\nPour donner une échelle : 100 000, c'est la population de Cannes, de\nBéziers, ou de Calais. C'est un stade de foot plein — deux fois.\nLe Chairman ne gère pas ces 100 000 personnes. Il ne les manage pas. Il\nne les connaît pas. Il ne les verra jamais. Il gère l'idée de ces 100 000\npersonnes — une abstraction financière appelée « la branche » ou « le\nsegment ».\nSa journée ?\nDes boards. Des conseils. Des comités stratégiques mondiaux. Des\nrencontres avec des investisseurs institutionnels — des fonds de pension,\ndes banques, des assureurs — qui possèdent des morceaux de l'entreprise\net veulent savoir si leur investissement est « performant ».\nLe mot « performant » est intéressant. À l'étage 0, être performant, c'est\nfaire un bon show. À l'étage 7, être performant, c'est générer du rendement\npour l'actionnaire.\nLe spectacle parfait de 10h30, celui qui fait pleurer les enfants de bonheur,\ncelui que le technicien a vérifié trois fois ce matin — ce spectacle n'existe\npas à l'étage 7. Il n'existe que sous forme de chiffre d'affaires par visiteur,\nnoyé dans un rapport de 200 pages que le Chairman survole dans un jet\nentre deux continents.\n58",
