      "text": "Le board : là où les destins se jouent\nC'est au board — au conseil d'administration — que les grandes décisions\nse prennent. Fermer un site. Ouvrir un marché. Céder une activité.\nSupprimer une division.\nAutour de la table : des gens en costume. Des avocats. Des banquiers\nd'affaires. Des administrateurs indépendants. Aucun — aucun —\nreprésentant de l'étage 0.\nLes décisions sont prises sur la base de slides financières. Des projections.\nDes modèles. Des scénarios. Tout est chiffré, modélisé, projeté.\nCe qui n'est pas chiffré n'existe pas.\nL'épuisement des équipes ? Pas chiffré. La perte de savoir-faire ? Pas\nchiffrée. La souffrance d'un CDD qui ne sera pas renouvelé ? Pas chiffrée.\nLe rendement de l'action ? Chiffré. À la quatrième décimale.\n59",
