      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 7 — LE CHAIRMAN\nPopulation gérée : 1 Chairman (supervision du conseil de surveillance)\nRémunération : x30 à x100 vs. terrain\n(salaire + actions + bonus)\nDistance au réel : inﬁnie\nContact avec le produit : uniquement cérémoniel\nInterlocuteurs : investisseurs, board, gouvernements\nProduit principal : rendement actionnarial\nUnité de mesure : le milliard\nMotivation : héritage, puissance, postérité\nVision du terrain : n'existe pas\n▌  VOIX DU TERRAIN\n« À chaque restructuration, on nous dit que c'est \"une décision difficile\nmais nécessaire\". Difficile. Pour qui ? Le Chairman a touché 8 millions\nd'euros cette année-là. Il était dans le rapport annuel, souriant, avec une\ncitation sur \"notre capital humain\". Nous, on était dans le plan social.\nOn n'était pas dans le rapport annuel. »\n— Opérateur de maintenance, 14 ans d'ancienneté, licencié lors d'une\nrestructuration\n60",
