      "pageNumber": 63,
      "text": "▌  LE SAVIEZ-VOUS ?\nEn France, en 2023, le salaire médian d'un PDG du CAC 40 était de 7\nmillions d'euros par an, soit environ 140 fois le salaire médian d'un salarié\nfrançais (26 200 €/an).\nEn 1965, aux États-Unis, ce ratio était de 21 pour 1. En 2023 : 290 pour 1.\nCe n'est pas un jugement moral. C'est une donnée. La même donnée que le\nChairman regarde dans ses tableaux de bord — sauf que dans ses tableaux\nde bord, elle s'appelle « politique de rémunération » et non « écart de\ndestin ».\nLes mots changent la réalité qu'on accepte.\n▲▼ ■ ■ ■ ■ ■ ■ ■ ■ □ ÉTAGE 7 SUR 9\nProchain étage — Le CEO. Le sommet. Celui qui signe.\n62",
