      "text": "ÉTAGE 8 — LE CEO\nLe sommet silencieux. Celui qui signe.\nCe chapitre est le plus court du livre. Volontairement. Parce qu'au sommet\nde la tour, il n'y a qu'une seule personne, un seul bureau, et un silence\nimmense.\n164 000 personnes.\nUn être humain, assis derrière un bureau, a la responsabilité théorique de\n164 000 autres êtres humains.\n164 000, c'est la population de Rennes, ou de Grenoble, ou d'Oxford, ou de\nSyracuse.\nLe CEO ne connaît pas ces gens. Il ne les connaîtra jamais. Il ne les verra\njamais. Il ne saura jamais leurs noms, leurs visages, leurs histoires, leurs\ntalents, leurs souffrances, leurs fiertés.\nEt pourtant, d'un trait de stylo, il peut changer leurs vies.\nCe qu'il voit\nDepuis le sommet, la vue est spectaculaire.\nLe CEO voit le monde. Les marchés mondiaux. Les tendances\nmacroéconomiques. Les mouvements géopolitiques. Les disruptions\ntechnologiques. Le cours de l'action. Le regard de Wall Street.\nCe qu'il ne voit pas :\nLe projecteur qui grille à l'étage 0.\n63",
