      "pageNumber": 65,
      "text": "Ce qu'il gagne\nLe CEO d'un grand groupe international gagne, en moyenne, entre 200 et\n500 fois le salaire d'un employé de terrain.\n200 à 500 fois.\nCela veut dire que ce que le terrain gagne en un an, le CEO le gagne en un\nou deux jours.\nCette phrase mérite d'être relue.\nCe que le terrain gagne en un an, le CEO le gagne en un jour ou deux.\nCe ratio n'a pas toujours existé. Dans les années 1960, il était de 20 contre\n1. Dans les années 1980, de 40 contre 1. Il a été multiplié par dix en\nsoixante ans.\nLe spectacle, lui, n'a pas été multiplié par dix. Il est toujours aussi bon.\nGrâce aux mêmes mains.\nCe qu'il fait\nLe CEO prend trois ou quatre décisions par an qui changent vraiment\nquelque chose. Le reste du temps, il représente, il incarne, il rassure les\nmarchés, il porte une vision.\nLes 364 autres jours, les spectacles tournent.\nSans lui.\n64",
