      "text": "▌  VOIX DU TERRAIN\n« Notre CEO a un salaire annuel de 36 millions de dollars. Il y a 164 000\npersonnes dans le groupe. Ça fait 220 dollars par personne. Si on\nrépartissait son seul salaire entre tous les employés du groupe, chacun\naurait un mois de courses en plus. Lui aurait une vie normale. Et\nl'entreprise tournerait exactement pareil. »\n— Calcul anonyme, partagé sur un forum interne\n▌  DONNÉES D'ÉTAGE\nÉTAGE 8 — LE CEO\nPopulation gérée : 1 CEO (35 000 salariés — l'ensemble du groupe)\nRémunération : x200 à x500 vs. terrain\nDistance au réel : ∞\nContact avec le produit : aucun\nInterlocuteurs : le board, Wall Street, la presse\nDécisions majeures : 3 à 4 par an\nUnité de mesure : le cours de l'action\n▌  Présence médiatique : supérieure à sa présence interne\nMotivation : postérité, pouvoir, héritage\n▌  Paradoxe : le plus payé, le plus loin du\ntravail réel\n65",
