      "pageNumber": 67,
      "text": "▌  LA QUESTION\nCe livre a commencé en bas. À l'étage 0. Là où le rideau se lève, là où le\npatient est soigné, là où le plat sort en cuisine, là où le mur est monté.\nOn est maintenant au sommet. Étage 8. 164 000 personnes en dessous.\nUne seule question reste :\nSi le terrain peut faire tourner le spectacle sans le sommet, mais que le\nsommet ne peut rien faire tourner sans le terrain —\nalors qui a besoin de qui ?\n▌  LE SAVIEZ-VOUS ?\nEn 1867, Karl Marx écrit dans Le Capital :\n« Le travail est la source de toute richesse. »\nEn 2024, le PDG le mieux payé du monde a gagné 281 millions de dollars.\nLe travailleur médian de sa propre entreprise a gagné 32 000 dollars.\nRatio : 1 pour 8 781.\nMarx n'avait pas prévu le chiffre. Mais il avait prévu la logique.\n▲▼ ■ ■ ■ ■ ■ ■ ■ ■ ■ ÉTAGE 8 SUR 9\nVous êtes au sommet de la tour.\nLa vue est magnifique. L'air est pur. Le silence est total.\nEn bas, le spectacle continue.\n66",
