      "text": "LA VUE D'ENSEMBLE\nAvant de quitter la tour, regardons-la une dernière fois. En entier.\n▌  RÉCAPITULATIF DE LA TOUR — DE L'ÉTAGE 8 AU TERRAIN\nNiveau Population Rémunération Focus Principal\nÉtage 8 — CEO 1 personne x200 à x500 3 décisions / an\nÉtage 7 — Chairman ~10 pers. x30 à x100 Rendement\nactionnarial\nÉtage 6 — Prés.\nInternational\n~10 pers. x15 à x30 Marchés globaux\nÉtage 5 — Prés.\nDivision\n~10 pers. x10 à x20 Communication &\nTown Halls\nÉtage 4 — Vice-\nPrésident\n~20 pers. x5 à x15 Budgets & Arbitrages\nÉtage 3 — Directeur ~50 pers. x3 à x5 Organigrammes &\nSites\nÉtage 2 — Resp.\nService\n~200 pers. x2 à x3 Réorganisations &\nProcess\nÉtage 1 — Manager\nProximité\n~2 000\npers.\nx1.3 à x2 Réunions & Plannings\nÉtage 0 — LE\nTERRAIN\n~160 000+ x1 (Socle) LE TRAVAIL RÉEL\nLa pyramide est claire.\nEn bas : beaucoup de monde, peu d'argent, tout le travail réel.\nEn haut : presque personne, tout l'argent, aucun travail réel.\n68",
