      "pageNumber": 70,
      "text": "Entre les deux  : des étages entiers consacrés à organiser, contrôler,\nmesurer, réorganiser, et justifier l'existence des étages.\nLa première partie de ce livre est terminée. On a monté la tour, étage\npar étage. On a vu ce qu'on y fait — et ce qu'on n'y fait pas.\nLa deuxième partie pose la question suivante :\nComment en est-on arrivé là ? Et surtout — comment en sort-on ?\n[ L'ascenseur redescend ]\n69",
