      "text": "Le CEO est désormais payé en stock-options — il est incité à faire\nmonter l'action, pas à rendre les gens heureux\nLes VP sont évalués sur la marge — ils coupent les coûts, c'est-à-dire\nles emplois\nLes réorganisations sont faites pour plaire aux analystes financiers,\npas pour améliorer le travail\nLe terrain devient officiellement ce qu'il était implicitement : un coût\nà minimiser\nLe \"headcount\" n'est pas un hasard linguistique. C'est la traduction directe\nde la doctrine Friedman : les gens sont un coût. Et un coût, ça se réduit.\nLa tour, résumée\nArchitecte Date Brique ajoutée\nTaylor 1911 Séparer ceux qui pensent de ceux qui font\nFord 1913 Standardiser le geste, rendre l'humain remplaçable\nLes MBA 1950-\n80\nFaire du management un métier déconnecté du\nterrain\nFriedman 1970 L'entreprise n'existe que pour les actionnaires\nChaque brique a été ajoutée pour une raison qui semblait rationnelle à son\népoque. Efficacité. Productivité. Rentabilité. Chaque brique a produit de la\ncroissance, de la richesse, du progrès matériel.\nMais chaque brique a aussi retiré quelque chose aux gens d'en bas :\n75",
