      "pageNumber": 77,
      "text": "Brique Ce qu'elle a retiré\nTaylor Le droit de penser au travail\nFord Le droit d'être unique au travail\nLes MBA Le droit de diriger sans diplôme de management\nFriedman Le droit d'être autre chose qu'un coût\nEt maintenant ?\nNous sommes en 2026. La tour est toujours debout. Mais ses fondations\ncraquent.\nParce que les gens qui sont en bas — ceux à qui on a retiré le droit de\npenser, d'être uniques, de diriger et d'être autre chose qu'un coût — ces\ngens commencent à dire non.\nPas avec des manifestations (quoique). Pas avec des révolutions (quoique).\nAvec quelque chose de plus silencieux et de plus puissant :\nIls partent.\nLe chapitre suivant raconte ce départ.\n▌  VOIX DU TERRAIN\n« J'ai fait un DUT, pas un MBA. Et pourtant, je sais exactement\ncomment organiser mon équipe, gérer un incident, former un nouveau,\net faire tourner un show de A à Z. Mais dans l'organigramme, je suis en\nbas. Parce que mon diplôme est en bas. Ce n'est pas une méritocratie.\nC'est une diplômacratie. »\n— Régisseur, secteur du spectacle vivant\n76",
