      "pageNumber": 78,
      "text": "« Mon responsable vient du marketing. Il n'a jamais touché un câble de\nsa vie. Il ne sait pas ce qu'est un gradateur. Mais c'est lui qui décide de\nnotre planning, de nos effectifs, de notre budget. Parce qu'il a un Master\nen Management. Moi j'ai quinze ans de terrain. Devinez qui comprend\nmieux le métier. »\n— Électricien, industrie de l'événementiel\n▌  LE SAVIEZ-VOUS ?\nAvant la révolution industrielle, la grande majorité des êtres humains\ntravaillaient selon un modèle que nous avons oublié : l'artisanat.\nL'artisan pense, conçoit, fabrique et vend. Il est responsable de tout. Il est\nautonome. Il est fier de son travail parce que c'est son travail — pas celui\nd'un ingénieur qu'il exécute.\nLa tour a été construite en détruisant l'artisan. En séparant sa tête de ses\nmains. En mettant sa tête en haut et ses mains en bas.\nLa question de notre époque n'est peut-être pas « comment réformer la\ntour ? »\nC'est peut-être « comment retrouver l'artisan ? »\n[ L'ascenseur est au sous-sol. On creuse les fondations. ]\nProchain chapitre — Le Grand Départ. Quand une génération entière\nrefuse de monter dans la tour.\n77",
