      "pageNumber": 80,
      "text": "Ce qui était\npromis\nCe qui est arrivé\nCDI = sécurité CDI = possibilité de licenciement économique, plan\nsocial, restructuration\nSalaire qui monte Salaire qui stagne pendant que tout augmente\nRetraite à 60 ans Retraite à 64, bientôt 65, peut-être 67\nLogement\naccessible\nUn studio coûte 15 ans de salaire dans les grandes villes\nTravailler dur =\nréussir\nTravailler dur = survivre\nLes jeunes n'ont pas rompu le contrat. Le contrat a été rompu pour eux.\nEt quand on leur reproche de ne pas vouloir s'engager, de ne pas être\n« loyaux » envers l'entreprise, de changer de job tous les deux ans — ils\nrépondent, avec une logique implacable :\n« Loyal envers quoi ? Envers un système qui ne tient aucune de ses\npromesses ? »\nLe mythe de la paresse\nIl faut en parler, parce que c'est l'argument-massue des étages supérieurs :\n« Les jeunes ne veulent plus travailler. »\nCette phrase est prononcée dans tous les comités de direction du monde.\nElle est confortable. Elle est simple. Elle met le problème sur les épaules de\n79",
