      "pageNumber": 81,
      "text": "ceux qui le subissent.\nMais regardons les faits.\nLes jeunes qui \"ne veulent plus travailler\" sont les mêmes qui :\nCréent des entreprises à 22 ans\nTravaillent 60 heures par semaine sur des projets qui les\npassionnent\nApprennent des langages de programmation le soir après le travail\nDéveloppent des applications gratuites pour résoudre des problèmes\nque leur entreprise ne résout pas\nEnchaînent les missions freelance dans des conditions précaires\nCe n'est pas le travail qu'ils refusent. C'est la tour.\nIls refusent de :\nFaire un travail qui n'a pas de sens\nObéir à un manager qu'ils n'ont pas choisi et qu'ils ne respectent pas\nAttendre une promotion basée sur l'ancienneté plutôt que sur le\ntalent\nSacrifier leur vie personnelle pour une entreprise qui les licenciera\nsans hésiter\nFaire semblant que la culture corporate est une \"famille\"\nLa différence entre les générations n'est pas une différence de courage ou\nd'éthique du travail. C'est une différence de tolérance à l'absurde.\nLes anciens ont toléré l'absurde parce que la contrepartie était réelle.\nLes jeunes ne tolèrent plus l'absurde parce que la contrepartie a disparu.\nL'école de l'obéissance\nPour comprendre pourquoi les jeunes se \"réveillent\", il faut comprendre\nd'où ils viennent. Et ils viennent de l'école.\n80",
