      "pageNumber": 82,
      "text": "L'école française — et la plupart des systèmes éducatifs occidentaux — est\nconstruite sur un modèle qui ressemble étrangement à la tour :\nL'ÉCOLE L'ENTREPRISE\nMinistère de l'Éducation ↔  CEO / Board\nRectorat ↔  Direction régionale\nProviseur ↔  Directeur de site\nProfesseur ↔  Manager\nÉlève ↔  Employé\nEt les mécanismes sont les mêmes :\nÀ l'école En entreprise\nNotes sur 20 Évaluation annuelle\nClassement Grille salariale / ranking\nBulletin trimestriel Reporting\nConseil de discipline Entretien disciplinaire\nRedoublement Non-promotion\n\"Peut mieux faire\" \"Axe d'amélioration identifié\"\nL'élève ne choisit pas son professeur L'employé ne choisit pas son manager\nLe programme est imposé d'en haut Les objectifs sont imposés d'en haut\nL'école ne forme pas des penseurs. Elle forme des exécutants notés. Elle\napprend à lever la main avant de parler, à attendre la permission, à\n81",
