      "pageNumber": 83,
      "text": "s'asseoir à la place assignée, à être évalué par quelqu'un qui a le pouvoir de\njuger.\nC'est l'antichambre de la tour.\nEt pendant des générations, ça a fonctionné. L'école formait les ouvriers de\nFord, les exécutants de Taylor, les managers des MBA. Tout le monde\nentrait dans le moule.\nSauf que les jeunes, aujourd'hui, voient le moule. Ils ont grandi avec\ninternet. Ils ont accès à toute l'information du monde. Ils peuvent\napprendre ce qu'ils veulent, quand ils veulent, sans attendre la permission\nd'un professeur. Et ils se demandent :\n« Pourquoi est-ce que quelqu'un qui me connaît à peine a le droit de me\nnoter sur 20 et de décider de mon avenir ? »\nCette question à l'école prépare une autre question au travail :\n« Pourquoi est-ce que quelqu'un qui ne connaît pas mon métier a le droit\nde m'évaluer et de décider de mon avenir ? »\nLe quiet quitting — la grève invisible\nEn 2022, un terme explose sur les réseaux sociaux : quiet quitting — la\ndémission silencieuse.\nLe principe : tu restes à ton poste. Tu fais ce qu'on te demande. Ni plus, ni\nmoins. Tu ne restes pas tard. Tu ne réponds pas aux mails le week-end. Tu\nne \"donnes pas plus\". Tu fais exactement ce pour quoi tu es payé — et pas\nune minute de plus.\nLes managers sont paniqués. « Ils ne s'investissent plus ! »\n82",
