      "text": "« On me dit \"tu n'es pas loyal envers l'entreprise.\" Je réponds :\n\"l'entreprise est-elle loyale envers moi ?\" Silence. »\n— Cuisinier, 26 ans\n▌  LE TRADUCTEUR\nCe que disent les étages\nsupérieurs\nCe que ça signifie pour le terrain\n« Les jeunes ne veulent plus\ntravailler »\nLes jeunes ne veulent plus travailler\npour vous\n« Il y a un problème\nd'engagement »\nIl y a un problème de raisons de\ns'engager\n« Ils n'ont pas l'esprit d'entreprise » Ils n'ont pas l'esprit de votre entreprise\n« Il faut attirer les talents » Il faut mériter les talents\n« La fidélisation est un enjeu clé » Rendez le travail supportable et ils\nresteront\n▌  LE SAVIEZ-VOUS ?\nEn 2021, aux États-Unis, 47 millions de personnes ont volontairement\nquitté leur emploi. On a appelé ça le Great Resignation — la Grande\nDémission.\nCe n'était pas une crise. C'était un vote. 47 millions de bulletins déposés\ndans l'urne silencieuse du marché du travail. 47 millions de gens qui ont\ndit, chacun dans leur coin, sans se concerter :\n« Non. »\n87",
