      "pageNumber": 92,
      "text": "2. FAVI — L'usine sans chef\nPicardie, France, années 1980.\nFAVI est une fonderie. Elle fabrique des fourchettes de boîtes de vitesses\npour l'automobile. C'est de l'industrie lourde. Du métal en fusion. Des\nmachines. Des ouvriers.\nQuand Jean-François Zobrist prend la direction en 1983, il fait quelque\nchose d'impensable : il supprime les contremaîtres, les pointeuses, et le\nservice des méthodes.\nIl organise l'usine en mini-usines de 20 à 30 personnes, chacune\nresponsable d'un client. Chaque mini-usine gère sa production, sa qualité,\nses délais. Les ouvriers parlent directement au client. Pas de commercial\nintermédiaire.\nLe résultat ?\nLeader européen de son marché pendant 30 ans\nZéro plan social en 30 ans\nAbsentéisme quasi nul\nLes ouvriers sont fiers — ils connaissent leur client, ils voient\nl'impact de leur travail\nLa phrase de Zobrist que nous avons déjà citée :\n« L'homme est bon. Il faut lui faire confiance. »\nCe n'est pas de la philosophie. C'est un business model. Et il a fonctionné\npendant trois décennies, dans une industrie aussi dure que la fonderie.\n91",
