      "pageNumber": 93,
      "text": "3. Les SCOP — L'entreprise appartient à ceux qui y\ntravaillent\nFrance, modèle existant depuis le XIXe siècle.\nUne SCOP (Société Coopérative et Participative) est une entreprise dont les\nsalariés sont les actionnaires majoritaires. Ils élisent leur dirigeant. Ils\nvotent les grandes décisions. Ils partagent les bénéfices.\nEn France, en 2024, il y a plus de 4 000 SCOP, dans tous les secteurs :\nChèque Déjeuner / Up Group — 3 700 salariés, leader des titres-\nrestaurant\nAcome — 1 800 salariés, fabricant de câbles, leader mondial\nAlma — logiciels industriels\nAmbiance Bois — scierie en Creuse, autogérée depuis 1988\nDes boulangeries, des agences web, des cabinets d'architectes, des\nimprimeries...\nLe principe fondamental :\nCelui qui fait le travail possède l'entreprise. Celui qui possède\nl'entreprise fait le travail.\nPas d'actionnaire extérieur qui exige 15 % de rendement. Pas de fonds de\npension qui impose des coupes. Le profit reste — et il est réinvesti ou\npartagé.\nLes SCOP ne sont pas parfaites. Elles ont leurs tensions, leurs lenteurs,\nleurs difficultés. Mais elles prouvent une chose : on peut produire, être\nrentable, et traiter les gens comme des êtres humains.\n92",
