      "text": "11 milliards d'euros de chiffre d'affaires\nIndustries, banque, distribution, université\nLe plus grand groupe coopératif du monde\nLe ratio salarial chez Mondragon ? 1 à 6 maximum entre le salaire le plus\nbas et le plus élevé. Pas 1 à 500. 1 à 6.\nQuand l'industrie basque traverse des crises, Mondragon ne licencie pas.\nLes coopérateurs acceptent une baisse temporaire de salaire, ou sont\nréaffectés dans une autre coopérative du groupe. La solidarité n'est pas un\nslogan — c'est une règle statutaire.\nLe point commun\nCes cinq exemples n'ont rien en commun en apparence. Des infirmiers\nnéerlandais, une fonderie picarde, des coopératives françaises, des\ndéveloppeurs du monde entier, des ouvriers basques.\nMais ils partagent trois principes :\nPrincipe 1 : La conﬁance remplace le contrôle\nDans tous ces modèles, on fait confiance aux gens pour faire leur travail.\nOn ne les surveille pas. On ne les note pas. On ne les classe pas. On leur\ndonne les moyens, les informations, et la liberté — et ils livrent.\nPrincipe 2 : La décision est au plus près du réel\nLes décisions ne montent pas 8 étages pour être prises par quelqu'un qui\nne comprend pas le problème. Elles sont prises par ceux qui vivent le\nproblème. L'infirmier décide pour son patient. L'ouvrier décide pour sa\nproduction. Le développeur décide pour son code.\nPrincipe 3 : La richesse est partagée\nLe profit ne remonte pas vers un actionnaire absent. Il est réparti entre\nceux qui le produisent. Pas par charité — par logique. Tu crées la valeur, tu\n94",
