      "text": "reçois la valeur.\nAlors pourquoi ?\nSi ces modèles existent, s'ils fonctionnent, s'ils sont plus humains ET plus\nperformants — pourquoi ne sont-ils pas partout ?\nLa réponse tient en une phrase :\nParce que ceux qui ont le pouvoir de changer le système sont ceux qui en\nbénéficient.\nLe VP qui gagne x15 le terrain n'a aucun intérêt à adopter le modèle\nMondragon où l'écart est de 1 à 6. Le Directeur qui justifie son existence\npar les réorganisations n'a aucun intérêt à supprimer les niveaux\nhiérarchiques. Le CEO qui gagne x500 n'a aucun intérêt à redistribuer.\nLe changement ne viendra pas d'en haut. Il n'en est jamais venu d'en haut.\nIl viendra du terrain. Comme toujours.\nLe cadre juridique alternatif — Reprendre le pouvoir légalement\nL'autonomie ne peut pas reposer uniquement sur la bonne volonté d'un\nmanager éclairé. Pour s'inscrire dans la durée, elle doit s'ancrer dans le\ndroit. En France et en Europe, plusieurs cadres juridiques permettent de\nprotéger la gouvernance partagée :\n1. La SCOP (Société Coopérative et Participative)\nLe principe : Les salariés sont les associés majoritaires (au moins\n51 % du capital et 65 % des droits de vote).\nRègle fondamentale : 1 personne = 1 voix, quel que soit le capital\ndétenu. Le pouvoir n'est pas proportionnel à l'argent versé.\n95",
