      "pageNumber": 100,
      "text": "CEUX QUI ONT DÉJÀ COMMENCÉ\nPas des révolutionnaires. Pas des démissionnaires. Des gens qui\nchangent les choses de l'intérieur.\nLe chapitre précédent vous a montré des modèles — Buurtzorg, FAVI,\nMondragon. Des noms. Des cas d'école. Des exemples qu'on cite en\nconférence.\nMais ce chapitre parle d'autre chose.\nIl parle de gens dont vous n'avez jamais entendu le nom. Des gens qui ne\npasseront jamais dans un TED Talk. Des gens qui ne savent même pas\nqu'ils sont en train de changer le monde.\nIls sont dans votre entreprise. Dans votre hôpital. Dans votre usine. Dans\nvotre école.\nIls n'ont pas quitté le navire. Ils n'ont pas brûlé la tour.\nIls l'ont reprogrammée de l'intérieur.\n1. Le technicien-inventeur\nIl s'appelle — peu importe comment il s'appelle. Ce qui compte, c'est ce\nqu'il a fait.\nPendant vingt ans, dans son entreprise, le planning des équipes se faisait\nsur une feuille Excel imprimée en A3, scotchée au mur, modifiée au crayon,\nphotographiée, envoyée par mail, re-modifiée, re-imprimée. Vingt ans.\nPersonne n'avait rien changé. Le management avait bien parlé d'un\n« projet de digitalisation du planning » — trois fois en dix ans. Trois\nprojets. Trois budgets. Trois consultants. Zéro résultat.\nLui, un soir, a ouvert un outil gratuit. Et il a construit une application.\nSimple. Claire. Fonctionnelle. En quelques semaines — pas quelques mois,\n99",
