      "text": "pas quelques années, quelques semaines — l'outil était prêt. Ses collègues\nl'ont adopté en deux jours. Plus de feuille A3. Plus de photo floue. Plus de\n« qui a modifié le planning sans prévenir ».\nLe management n'a pas demandé l'application. Le management n'a pas\nfinancé l'application. Le management n'a même pas su que l'application\nexistait pendant les trois premiers mois.\nEt quand ils l'ont découverte, ils ont eu deux réactions, dans cet ordre :\n1. « C'est pas validé par la DSI. »\n2. «...Mais ça marche vachement bien. »\nL'application est toujours en service.\nPourquoi c'est important :\nCe technicien n'est pas un cas isolé. Il existe dans chaque entreprise. Dans\nchaque usine, chaque hôpital, chaque restaurant, il y a quelqu'un qui a\nbricolé un outil, inventé un procédé, trouvé un raccourci — parce que le\nsystème officiel ne marchait pas, parce que personne en haut ne\ncomprenait le problème, ou simplement parce que personne n'a demandé à\nla bonne personne.\nL'innovation, la vraie, ne descend pas d'un comité stratégique. Elle monte\ndu sol. Elle vient des mains de ceux qui touchent le problème chaque jour.\nLe terrain n'attend pas la permission pour résoudre les problèmes. Il\nattend juste qu'on arrête de l'en empêcher.\n2. L'infirmière qui a dit non\nElle travaille dans un service de gériatrie. Vingt-deux lits. Trois infirmières\nle matin, deux l'après-midi, une la nuit. Chaque minute compte. Chaque\n100",
