      "text": "Ce qui s'est aussi passé : Mme Durand a souri plus souvent. M. Khelil a\naccepté son traitement sans résister. L'ambiance du service,\nimperceptiblement, s'est allégée.\n150 heures par an. Rendues aux patients. Par une femme qui a simplement\ndécidé que les gens passent avant les formulaires.\nDans chaque organisation, il y a des formulaires REA-7. Des procédures\nque personne n'a jamais questionnées. Des rituels administratifs dont\nplus personne ne connaît l'origine. Si demain, vous arrêtiez de les\nremplir — combien de temps est-ce que quelqu'un mettrait à s'en\napercevoir ?\n3. Le manager qui est redescendu\nThomas avait « réussi ». Selon les critères de la tour, il avait coché toutes\nles cases.\nÀ 28 ans : technicien. Excellent. Le meilleur de son équipe. À 32 ans :\npromu chef d'équipe. « Évolution naturelle. » À 36 ans : responsable de\nservice. Bureau individuel. Réunions de direction. À 39 ans  : vidé.\nComplètement vidé.\nPas de burn-out spectaculaire. Pas de dépression clinique. Quelque chose\nde plus insidieux : un vide. Le sentiment, chaque matin, de ne rien faire de\nréel. De passer ses journées dans des réunions où l'on parle de choses qu'il\nne touchait plus. De valider des décisions qu'il ne comprenait plus, parce\nqu'il avait perdu le contact avec la matière.\nThomas aimait son métier. Le vrai. Celui des mains, du terrain, de la\nrésolution de problèmes concrets. Il était devenu manager parce que c'était\nle seul chemin que la tour proposait pour « avancer ». Rester technicien,\nc'était « plafonner ». Monter, c'était « évoluer ».\n102",
