      "text": "Personne ne lui avait dit que monter pouvait aussi signifier s'éloigner de ce\nqui vous rend vivant.\nÀ 40 ans, Thomas a fait le chemin inverse. Il est redescendu.\nVolontairement. Pas comme une sanction. Comme un choix.\nLa réaction de l'entreprise ? La stupeur. Puis l'incompréhension. Puis, dans\ncertains regards, une pointe d'admiration inavouée.\nCe qu'il a perdu :\n20 % de salaire\nUn bureau individuel\nUne place de parking\nUn titre sur sa carte de visite\nCe qu'il a gagné :\nLe sommeil\nLa fierté de voir un résultat concret à la fin de chaque journée\nLe respect de son équipe — un respect différent, plus profond, celui\nqu'on accorde à quelqu'un qui a choisi d'être là\nLe lundi matin sans nœud à l'estomac\nQuand on lui demande s'il regrette, Thomas rit.\n« On me demandait de piloter des dashboards. Maintenant je résous des\nproblèmes. J'ai perdu un titre et un parking. J'ai retrouvé un métier. »\nPourquoi c'est important :\nThomas prouve que la tour ment sur un point crucial : monter n'est pas la\nseule direction valide. Descendre peut être un acte de courage. De lucidité.\nDe reconquête.\n103",
