      "pageNumber": 108,
      "text": "Feedback mensuel, par les pairs : chaque mois, chaque membre de\nl'équipe donne un retour court (3 questions : qu'est-ce que cette\npersonne fait bien ? qu'est-ce qu'elle pourrait améliorer ? de quoi a-\nt-elle besoin ?)\nLes objectifs sont fixés par l'équipe, pas par le manager\nLe manager reçoit aussi du feedback. De son équipe. Anonyme\nLa prime est collective, pas individuelle  : si l'équipe atteint ses\nobjectifs, tout le monde en bénéficie\nLa résistance :\nOh, la résistance a été féroce. Pas du terrain — le terrain a adoré. La\nrésistance est venue d'en haut.\nLe Directeur financier : « Si on ne note pas les gens, comment on\njustifie les augmentations ? »\nLe DG adjoint : « Le feedback anonyme, ça va devenir un tribunal. »\nCertains managers  : «  Si mon équipe me note, je perds toute\nautorité. »\nSophie a tenu. Elle a dit : « Essayons pendant un an. Si les résultats sont\nmauvais, on revient en arrière. Mais donnez-moi un an. »\nLes résultats après un an :\nIndicateur Services classiques Services pilotes\nSatisfaction des salariés 5,2/10 7,8/10\nTurnover 18 % 6 %\nAbsentéisme 7,5 % 3,1 %\nAtteinte des objectifs 62 % 84 %\nCandidatures spontanées 3/mois 14/mois\n107",
