      "pageNumber": 109,
      "text": "Le bouche-à-oreille avait fait son travail. Les gens des autres services\ndemandaient à intégrer le pilote. Les candidatures spontanées avaient\nquadruplé — non pas parce que le salaire était meilleur, mais parce que les\ngens avaient entendu dire qu'ici, on était traité comme un adulte.\nDeux ans plus tard, le système était étendu à l'ensemble de l'entreprise.\nSophie n'a pas dynamité la tour. Elle a ouvert une porte. Et les gens se sont\nengouffrés dedans.\nLe fil rouge\nCes cinq histoires n'ont rien de spectaculaire. Pas de barricade. Pas de\nmanifestation. Pas de démission fracassante. Pas de thread viral sur\nLinkedIn.\nCe sont des actes silencieux. Des gens qui, un matin, ont décidé que le\nsystème tel qu'il était ne leur convenait pas — et qui, au lieu de partir ou de\nse résigner, ont fait autrement.\nLe technicien qui a codé une solution que le management n'a pas su\nproduire en vingt ans. L'infirmière qui a choisi les patients plutôt que les\nformulaires. Le manager qui a choisi le sens plutôt que le statut. L'équipe\nqui a prouvé qu'elle n'avait pas besoin de chef. La DRH qui a changé les\nrègles du jeu.\nIls sont partout. Dans votre entreprise aussi.\nPeut-être que vous êtes l'un d'entre eux.\n108",
