      "text": "▌  VOIX DU TERRAIN\n« J'ai mis trois mois à convaincre mes collègues qu'on pouvait gérer le\nplanning nous-mêmes. Trois mois de plus pour que ça devienne une\nhabitude. Et encore trois mois pour que le management arrête de\npaniquer. Neuf mois en tout. L'ancien système avait mis vingt ans à ne\npas marcher. »\n— Technicien logistique, industrie automobile, Alsace\n« Quand j'ai arrêté de remplir des tableaux de suivi que personne ne\nlisait, j'ai gagné 45 minutes par jour. J'ai utilisé ce temps pour former\nles nouvelles recrues. Le turnover de mon équipe a baissé de moitié en\nsix mois. Personne ne m'a demandé pourquoi. Personne ne m'a félicité\nnon plus. Mais je sais. »\n— Aide-soignante, EHPAD, Gironde\n« Je suis redescendu de mon poste de directeur d'agence. Ma mère m'a\ndit que j'avais gâché ma carrière. Mon équipe m'a dit que j'avais gagné\nleur respect. Devinez lequel des deux me rend plus fier. »\n— Ex-directeur d'agence, désormais conseiller clientèle, banque\nrégionale\n« Quand le nouveau DRH a instauré le feedback par les pairs, les\nmanagers les plus médiocres ont paniqué. Les meilleurs ont dit : \"Enfin.\"\nÇa vous dit tout ce qu'il faut savoir sur qui avait peur de la\ntransparence. »\n— Responsable qualité, entreprise agroalimentaire, Bretagne\n109",
