      "text": "▌  LE SAVIEZ-VOUS ?\nSelon une étude de l'Institut Gallup (2023), seulement 6 % des salariés\nfrançais se disent activement engagés dans leur travail. C'est l'un des taux\nles plus bas au monde.\nMais voici le chiffre que personne ne cite : parmi les entreprises qui ont\nmis en place des pratiques d'autonomie réelle (décision par les équipes,\ntransparence, feedback horizontal), le taux d'engagement monte à 48 %.\nLe problème n'est pas que les Français ne veulent pas travailler. Le\nproblème est que le système dans lequel on leur demande de travailler a été\nconçu pour les démotiver.\nChangez le système. Les gens suivront.\n[ L'ascenseur a touché le fond. Il est temps de remonter. Mais cette fois,\navec des outils. ]\nProchain chapitre — Fiches Pratiques. Des actions concrètes pour lundi\nmatin.\n110",
