      "text": "FICHES PRATIQUES — PAR OÙ\nCOMMENCER\nSept actions concrètes pour lundi matin\nCe chapitre ne ressemble à aucun autre dans ce livre.\nPas de récit. Pas de métaphore. Pas de tour.\nJuste des fiches. Sept fiches pratiques. Chacune est une action que vous\npouvez lancer dès la semaine prochaine — pas dans trois ans, pas après une\nréorganisation, pas après le prochain Town Hall.\nCertaines sont pour les managers. D'autres pour les salariés. Toutes sont\npour ceux qui en ont assez de décrire les problèmes et qui veulent\ncommencer à les résoudre.\n111",
