      "text": "L'AUDIT DE RÉUNIONS\nFiche pratique 1\nObjectif  : Rendre visible le temps perdu en réunions inutiles — et le\nrécupérer.\nPour qui : Tout le monde. Mais surtout les managers qui organisent les\nréunions.\nDurée de mise en place : 1 semaine d'observation + 1 heure de bilan.\nLes étapes\n1. Comptez. Pendant une semaine, notez chaque réunion à laquelle\nvous participez. Pour chacune, remplissez ce tableau :\nRéunion Durée Participants Ma\nprésence\nnécessaire ?\nUne\ndécision\na été\nprise ?\nAurait\npu être\nun\nemail ?\nEx: Point\nhebdo\n1h 12 Non Non Oui\n2. Calculez le coût réel. Pour chaque réunion inutile, multipliez la\ndurée par le nombre de participants. C'est le nombre d'heures-\npersonne perdues.\n112",
