      "pageNumber": 119,
      "text": "LE COORDINATEUR TOURNANT\nFiche pratique 4\nObjectif : Remplacer le chef permanent par un rôle de coordination qui\ntourne entre les membres de l'équipe.\nPour qui : Équipes de 5 à 20 personnes, tous secteurs.\nDurée de mise en place : 1 mois pour le premier cycle complet.\nLes étapes\n1. Définissez le rôle. Le coordinateur n'est pas un chef. Il ne donne pas\nd'ordres. Il ne note personne. Son rôle :\nAnimer le brief du matin\nÊtre le point de contact pour les autres services\nS'assurer que les décisions sont prises (pas les prendre seul)\nRésoudre les blocages du quotidien\n2. Établissez la rotation. Chaque personne occupe le rôle pendant un\nmois. Pas de volontariat obligatoire — mais pas d'exclusion non plus.\nTout le monde essaie.\n3. Faites un bilan après chaque rotation. 15 minutes à la fin du mois.\nDeux questions :\nQu'est-ce que tu as appris en étant coordinateur ?\nQu'est-ce qu'on peut améliorer dans le fonctionnement ?\nPourquoi ça marche :\nChaque membre de l'équipe comprend la complexité de la\ncoordination (adieu les « le chef, il fait quoi de ses journées ? »)\n118",
