      "pageNumber": 120,
      "text": "Chaque personne apporte ses forces : l'un est bon en organisation,\nl'autre en communication, l'autre en résolution de conflits. Le\nmeilleur leader du lundi n'est pas toujours le meilleur du vendredi\nPersonne ne s'installe dans le pouvoir. Le pouvoir circule. Et quand\nle pouvoir circule, il ne corrompt plus\nRésultat attendu : Après 6 mois de rotation, les équipes rapportent en\nmoyenne une hausse de 25 % de la satisfaction interne et une meilleure\nprise de décision — parce que les décisions sont prises par quelqu'un qui\nsait qu'il sera du côté de l'exécution le mois suivant.\n119",
