      "pageNumber": 121,
      "text": "L'INNOVATION DU TERRAIN\nFiche pratique 5\nObjectif : Créer un canal simple et réactif où n'importe qui peut proposer\nune amélioration — et obtenir une réponse.\nPour qui : Toute organisation. Toute taille.\nDurée de mise en place : 1 semaine.\nLes étapes\n1. Créez le canal. Physique ou numérique, peu importe. Une boîte à\nidées (oui, vraiment — mais une qui fonctionne). Un formulaire en\nligne. Un tableau blanc dans la salle de pause. Un canal Slack. Le\nsupport ne compte pas. Ce qui compte, c'est la règle :\nToute proposition reçoit une réponse sous 7 jours. Pas nécessairement\n« oui ». Mais jamais le silence.\nC'est la règle la plus importante. Parce que le silence tue l'initiative plus\nsûrement que le refus. Un « non, et voici pourquoi » est infiniment plus\nrespectueux qu'un tiroir qui ne s'ouvre jamais.\n2. Définissez le format. Simple. Trois champs :\nLe problème (en 2 phrases)\nMa proposition (en 2 phrases)\nCe qu'il faudrait pour essayer (temps, budget, accord de qui ?)\n3. Répondez. Vraiment. Avec honnêteté. Trois réponses possibles :\n« On essaie » — et on fixe une date\n120",
