      "pageNumber": 124,
      "text": "Ce dernier point est fondamental. Si l'échec est puni, personne n'essaiera.\nEt si personne n'essaie, rien ne changera jamais.\nRésultat attendu  : Les organisations qui institutionnalisent le droit à\nl'expérimentation voient en moyenne 3 fois plus d'initiatives de la part des\néquipes — et les innovations qui émergent sont plus adaptées au terrain\nque celles qui descendent du comité de direction.\nLa tour a peur de l'expérimentation parce qu'elle a peur de l'échec. Mais\nl'échec d'une expérimentation de 3 mois coûte infiniment moins cher que\n10 ans de statu quo.\n123",
