      "pageNumber": 125,
      "text": "POUR LE SALARIÉ — REPRENDRE DU\nPOUVOIR\nFiche pratique 7\nObjectif : Donner des outils concrets à ceux qui n'ont pas de pouvoir\nhiérarchique — mais qui veulent reprendre du contrôle sur leur travail.\nPour qui : Vous. Le terrain. L'étage 0.\nDurée de mise en place : Immédiat. Continu.\nLes étapes\n1. Documentez vos innovations. Chaque fois que vous trouvez une\nmeilleure façon de faire — même petite, même évidente — écrivez-la.\nUn carnet. Un fichier. Un post-it. Peu importe.\nPourquoi ? Parce que votre connaissance est invisible. Le jour où quelqu'un\nvous dira « vous êtes remplaçable », vous pourrez poser ce carnet sur la\ntable et dire  : «  Voici 47 améliorations que j'ai apportées en 3 ans.\nRemplacez ça. »\n2. Construisez des alliances. Vous n'êtes pas seul. Dans votre équipe,\ndans votre service, il y a d'autres personnes qui pensent comme\nvous. Qui voient les mêmes absurdités. Qui rêvent des mêmes\naméliorations. Trouvez-les. Parlez-leur. Pas pour vous plaindre —\npour construire.\nTrois personnes qui proposent ensemble ont plus de poids qu'une\npersonne seule. Dix personnes qui proposent ensemble sont impossibles à\nignorer.\n124",
