      "pageNumber": 127,
      "text": "Ne l'oubliez jamais.\n▌  VOIX DU TERRAIN\n« On m'a dit pendant 10 ans que j'étais remplaçable. Et puis j'ai pris ma\nretraite. Ils ont mis trois intérimaires pour me remplacer. Et six mois\npour que les trois ensemble atteignent ma productivité. J'étais\nremplaçable, mais par trois personnes et six mois de formation. C'est ça,\nle vrai coût du mépris. »\n— Ouvrier retraité, industrie métallurgique, Loire\n« Avec quatre collègues, on a commencé à documenter nos\naméliorations. En un an, on en avait 83. Quand notre responsable a\nvoulu supprimer un poste dans l'équipe, on a sorti la liste. \"Supprimez\nqui vous voulez. Mais supprimez aussi les 83 choses que cette personne a\ncréées.\" Le poste a été maintenu. »\n— Agent de maintenance, collectivité territoriale, Var\nLe mot de la fin (de ce chapitre)\nCes sept fiches ne vont pas changer le monde. Pas toutes seules. Pas du\njour au lendemain.\nMais elles peuvent changer votre lundi matin. Et si votre lundi matin\nchange, celui de vos collègues changera aussi. Et de proche en proche, fiche\npar fiche, équipe par équipe, la tour commencera à bouger.\nPas parce que quelqu'un au 8ème étage l'a décidé.\nParce que quelqu'un au rez-de-chaussée a commencé.\n126",
