      "pageNumber": 132,
      "text": "◌  LE SAVIEZ-VOUS ? Les recherches en psychologie organisationnelle\n(Kotter, 1996; Higgs & Rowland, 2005) montrent que 70 % des projets\nde transformation échouent — et que les causes principales sont toujours\nles mêmes : manque d'implication des équipes terrain, rythme trop\nrapide, et absence de preuves concrètes de progrès. Le changement qui\nréussit est presque toujours incrémental, volontaire et basé sur des\nrésultats mesurables.\n2. La logique des cercles concentriques\nSi le Grand Soir ne marche pas, qu'est-ce qui marche ? Un modèle simple,\ntesté dans des dizaines d'organisations : les cercles concentriques.\nImaginez un caillou jeté dans l'eau. Il crée un premier cercle, petit, puis un\ndeuxième, plus grand, puis un troisième. Chaque cercle naît du précédent.\nLa transition fonctionne exactement comme ça :\nCercle 1 : UNE équipe (3-6 mois)\nTout commence par une seule équipe. Pas un département. Pas un service.\nUne équipe. Cinq à quinze personnes qui veulent essayer.\nRègle absolue : cette équipe doit être volontaire. Jamais désignée. Jamais\nforcée. Si vous devez convaincre les gens de participer à un projet de\nlibération, c'est que quelque chose ne va pas dans votre approche.\nCette équipe pilote reçoit un cadre clair :\nDes objectifs mesurables (qualité, délais, satisfaction client,\nsatisfaction interne)\nUne liberté accrue sur un périmètre défini (par exemple : auto-\norganisation des plannings, suppression d'une couche de validation,\nbudget autonome pour les achats de moins de 500 €)\n131",
