      "pageNumber": 133,
      "text": "Un engagement de documentation  : tout est noté, les réussites\ncomme les échecs\nCercle 2 : UN service (6-12 mois)\nSi l'équipe pilote produit des résultats — et seulement si elle en produit —\nle cercle s'élargit. D'autres équipes du même service demandent à rejoindre\nle mouvement. Le mot-clé : demandent. Vous ne proposez pas. Vous ne\nvendez pas. Vous laissez les résultats parler.\nC'est exactement ce qui s'est passé chez Buurtzorg. Jos de Blok n'a pas\nenvoyé de directive aux 10 000 infirmières des Pays-Bas. Il a lancé une\néquipe de 4 personnes. Quand les résultats ont été spectaculaires (35 % de\ncoûts en moins, satisfaction patients au sommet), d'autres infirmières ont\ndemandé  : «  On peut faire pareil  ?  » En cinq ans, 850 équipes\nfonctionnaient sur le même modèle. Sans jamais forcer personne.\nCercle 3 : UN département (12-24 mois)\nLe service entier fonctionne différemment. Les résultats sont consolidés.\nLes autres départements commencent à remarquer. La direction\ncommence à s'intéresser — non pas par conviction idéologique, mais parce\nque les chiffres sont meilleurs.\nCercle 4 : L'organisation (24-60 mois)\nLe nouveau modèle devient la norme. Non pas parce qu'il a été imposé,\nmais parce qu'il a démontré sa supériorité sur chaque métrique qui\ncompte.\n132",
