      "pageNumber": 134,
      "text": "◌  LE TRADUCTEUR\nCe que dit le\nterrain\nCe que la\ndirection\nentend\nComment traduire\n« On veut plus\nd'autonomie »\n« Ils veulent\nfaire n'importe\nquoi »\n« On propose un pilote de 3\nmois avec des KPIs précis »\n« La pointeuse est\nabsurde »\n« Ils veulent\narriver en\nretard »\n« On souhaite tester l'auto-\ndéclaration pour réduire les\ncoûts administratifs »\n« Les réunions ne\nservent à rien »\n« Ils veulent\nêtre hors\ncontrôle »\n« On propose de diviser par\ndeux les réunions et mesurer\nl'impact sur la productivité »\n« On n'a pas\nbesoin de N+2 »\n« Ils veulent\nma tête »\n« On propose de tester la\ncoordination tournante au sein\nde l'équipe pilote »\nLe secret des cercles concentriques, c'est qu'ils inversent la charge de la\npreuve. Ce n'est plus le terrain qui doit prouver que le changement est\npossible. C'est la direction qui doit expliquer pourquoi elle refuse d'étendre\nce qui marche.\n3. Objections légitimes et réponses honnêtes\nTout ce qui précède semble raisonnable. Trop raisonnable, peut-être. Parce\nque dans la vraie vie, quand vous proposez un pilote d'autonomie à votre\nN+1, vous n'obtenez pas un hochement de tête approbateur. Vous obtenez\ndes objections. Certaines de mauvaise foi. Mais d'autres — et c'est\nimportant de le reconnaître — tout à fait légitimes.\n133",
