      "text": "personnes — les rôles. C'est une distinction essentielle, mais elle ne suffit\npas à rassurer quand c'est votre poste qui est en jeu.\n◌  LE TRADUCTEUR\nRôle actuel du manager Ce qui se passe dans la transition\nManager-contrôleur\n(surveille, valide, approuve)\nDisparaît. Remplacé par l'auto-\ncontrôle de l'équipe et la transparence\ndes résultats.\nManager-relais\nd'information (fait circuler\nl'info entre haut et bas)\nDisparaît. L'information circule\ndirectement (outils numériques,\ntransparence).\nManager-politique (gère sa\ncarrière, protège son\nterritoire)\nDisparaît. La transparence tue la\npolitique — et personne ne le pleurera.\nManager-expert (apporte\nune compétence technique\nirremplaçable)\nSe transforme. Reste expert, perd le\ntitre « manager ». Gagne en\npertinence, perd en pouvoir\nhiérarchique.\nManager-coach (développe\nles gens, résout les conflits)\nSe transforme. Devient facilitateur ou\ncoach à temps plein. Son rôle est enfin\nreconnu pour ce qu'il est.\nManager-protecteur (défend\nson équipe contre la\nbureaucratie)\nSe transforme. Devient coordinateur\nélu, rôle tournant. L'équipe choisit qui\nla représente.\nRegardons les choses en face  : dans cette grille, les managers qui\n« perdent » sont ceux dont le rôle ne créait déjà aucune valeur — ou pire,\nen détruisait. Le manager qui passait son temps à valider des notes de frais\n139",
