      "pageNumber": 141,
      "text": "de 23 euros ne manquera à personne. Le manager qui protégeait son\néquipe et développait les compétences de chacun ? Celui-là, non seulement\nil ne perd rien, mais il gagne : enfin, son rôle est reconnu pour ce qu'il est\nréellement, plutôt que noyé dans de l'administratif inutile.\nCe que montrent les exemples :\nChez Buurtzorg, quand Jos de Blok a lancé les équipes autonomes, il y avait\ndans l'organisation précédente (les soins à domicile classiques aux Pays-\nBas) des couches et des couches de management. Lors de la transition,\ndeux managers ont perdu leur poste. Voici ce qui s'est passé :\nLe premier est devenu coach régional — il aidait les nouvelles\néquipes à s'organiser. Il a retrouvé du sens dans son travail.\nLe second est retourné au métier d'infirmier. Après vingt ans de\nmanagement, il a recommencé à soigner des patients. Lors d'une\ninterview, il a confié : « Je n'ai jamais été aussi heureux. J'avais\noublié pourquoi j'avais choisi ce métier. »\nPersonne n'a été « jeté ». Le rôle a changé. Pour certains, c'était un gain.\nPour d'autres, c'était un deuil — le deuil du statut, du pouvoir, du titre sur\nla carte de visite. Ce deuil est réel et il faut le respecter. Mais il ne justifie\npas de maintenir un système qui ne fonctionne pas pour tout le monde.\n◌  VOIX DU TERRAIN « Mon manager était un ancien technicien\nbrillant. Le jour où on a supprimé son poste de \"responsable d'équipe\", il\na eu peur. Six mois plus tard, il était redevenu technicien — avec 30 % de\nsalaire en moins mais 100 % de passion en plus. Il m'a dit : \"J'avais\noublié que j'aimais ce métier. Le management m'avait volé ça.\" » —\nSarah, technicienne en maintenance industrielle, Dunkerque\n140",
