      "pageNumber": 142,
      "text": "◌  LA QUESTION Si votre manager disparaissait demain, que se\npasserait-il concrètement dans votre équipe ? Qu'est-ce qui s'arrêterait…\net qu'est-ce qui continuerait exactement comme avant ? La réponse à\ncette question vous dit tout ce que vous devez savoir sur l'utilité réelle de\nce rôle.\n« Et si ça échoue ? »\nÇa arrive. Il faut le dire clairement : toutes les transitions ne réussissent\npas.\nZappos, on l'a vu, a connu un désastre avec l'holacratie imposée. Morning\nStar, l'entreprise californienne de transformation de tomates souvent citée\nen exemple d'autogestion, a elle aussi connu des périodes difficiles — des\ntensions internes sur les salaires, des conflits non résolus qui pourrissaient\nfaute de mécanisme clair de médiation. Certaines SCOP font faillite —\ncomme n'importe quelle entreprise. Le statut coopératif ne protège pas de\nla mauvaise gestion ou du marché.\nMais quand on analyse les échecs, un schéma apparaît. Les transitions qui\néchouent partagent presque toujours les mêmes causes :\n1. Trop vite. Changement imposé en quelques semaines sur une\norganisation entière, sans phase pilote.\n2. Trop dogmatique. Application aveugle d'un modèle (holacratie,\nsociocratie, « entreprise libérée ») sans l'adapter au contexte local.\n3. Trop top-down. Le paradoxe suprême : imposer l'autonomie par la\nhiérarchie. « Vous êtes libres, c'est un ordre. »\n4. Pas de formation. On demande aux gens de s'auto-organiser sans\nleur apprendre à le faire. L'autogestion, ça s'apprend. La facilitation,\nça s'apprend. La gestion de conflit entre pairs, ça s'apprend.\n5. Pas de droit à l'erreur. Au premier problème, on revient à l'ancien\nsystème. « Vous voyez, ça ne marche pas. » Alors qu'on n'accorde\n141",
