      "pageNumber": 147,
      "text": "Clause de sortie (si ça ne marche pas, on revient en arrière sans\nstigmatisation)\nRetirez UNE contrainte inutile par pilote. Pas dix. Une seule. Exemples :\nL'équipe A supprime la pointeuse et passe à l'auto-déclaration\nL'équipe B supprime le reporting hebdomadaire et le remplace par\nun tableau de bord visible par tous\nL'équipe C supprime la chaîne de validation pour les achats\ninférieurs à 300 €\nMesurez les résultats — honnêtement. Documentez aussi les problèmes. Si\nl'équipe A a un problème d'assiduité après la suppression de la pointeuse,\nécrivez-le. Si l'équipe B est plus productive sans le reporting, écrivez-le. La\ncrédibilité du projet repose sur son honnêteté.\n◌  LE TRADUCTEUR\nMétrique terrain Métrique direction Comment relier\nles deux\n« On perd moins de\ntemps »\n« Productivité\n+12 % »\nComparer heures-\ntâche avant/après\n« L'ambiance est\nmeilleure »\n« Turnover -8 % » Enquête satisfaction\n+ données RH\n« On résout les\nproblèmes plus vite »\n« Délai moyen de\nrésolution -30 % »\nSuivi des tickets /\nincidents\n« Les clients sont\ncontents »\n« NPS +15 points » Enquête client ciblée\nsur l'équipe pilote\n146",
