      "pageNumber": 148,
      "text": "Année 2 : Étendre\nSi les pilotes marchent — et seulement s'ils marchent — élargissez.\nÉtendez au service entier. Les équipes non-pilotes du même service\nrejoignent le mouvement. Toujours sur la base du volontariat, mais\ncette fois avec des résultats concrets à montrer.\nFormez des coordinateurs. Pas des managers — des coordinateurs.\nLe rôle est tournant (tous les 6 à 12 mois), élu par l'équipe, centré\nsur la facilitation. Formez-les  : gestion de conflit, animation de\nréunion, prise de décision collective.\nCommencez la transparence salariale. Progressivement :\nD'abord les fourchettes anonymes (« dans ce service, les salaires\nvont de X à Y »)\nPuis les grilles par fonction (« un technicien niveau 3 gagne entre X\net Y »)\nPuis, si l'équipe le souhaite, les montants individuels\n◌  VOIX DU TERRAIN « Quand on a étendu le pilote à tout le service,\nj'avais peur que les nouvelles équipes ne soient pas prêtes. En fait, elles\nnous avaient observés pendant un an. Elles savaient déjà comment\nfaire. Elles n'attendaient que la permission. » — Rachid, infirmier\ncoordinateur en HAD, Marseille\nAnnée 3 : Structurer\nPassez de l'expérience à l'institution.\nLe changement ne peut pas rester informel indéfiniment. Il faut le codifier\n— non pas pour le bureaucratiser, mais pour le protéger. Sinon, un\nchangement de direction suffira à tout défaire.\nCréez un cadre formel pour les équipes autonomes  : charte,\nprincipes de fonctionnement, mécanismes de décision, gestion des\n147",
