      "text": "Prendre des micro-décisions sans demander la permission (si c'est\nréversible et de faible enjeu)\nCréer des espaces de discussion informels (un café mensuel, un\ngroupe de discussion)\n◌  VOIX DU TERRAIN « Sur le chantier, on a arrêté d'attendre la\nvalidation du bureau d'études pour les ajustements mineurs. On notait,\non ajustait, on signalait après. On gagnait deux jours par semaine.\nQuand le chef de projet a vu les délais baisser, il n'a pas demandé\ncomment. Il a juste dit : \"Continuez.\" » — Mamadou, chef de chantier\ndans le BTP, Île-de-France\n5. Connaissez vos droits\nVous avez des droits que vous ne connaissez probablement pas :\nDroit d'expression (L.2281-1 du Code du travail) : vous pouvez vous\nexprimer sur l'organisation du travail. Directement. Collectivement.\nC'est un droit, pas une faveur.\nDroit d'alerte : si vous constatez un danger grave et imminent, ou\nune atteinte aux droits des personnes, vous pouvez alerter\nl'employeur et le CSE.\nDroit de retrait (L.4131-1) : si vous estimez que votre situation de\ntravail présente un danger grave et imminent, vous pouvez vous\nretirer de votre poste.\nCSE : les élus du CSE ont un droit de consultation sur l'organisation\ndu travail. Si vous êtes élu, utilisez-le. Si vous ne l'êtes pas, parlez à\nvos élus.\nLe changement le plus puissant ne vient pas d'en haut. Il vient de gens\nordinaires qui décident que les choses peuvent être différentes — et qui le\nprouvent.\n151",
