      "pageNumber": 155,
      "text": "◌  LE TRADUCTEUR\nSecteur Hiérarchie pour la\nsécurité\nAutonomie possible\nNucléaire Procédures critiques,\nchaîne de décision en cas\nd'incident\nOrganisation\nquotidienne, formation,\nlogistique\nAviation Vol, protocoles d'urgence Maintenance, plannings,\namélioration continue\nSanté Bloc opératoire, protocoles\nmédicaux, urgences\nSoins courants,\norganisation d'équipe,\nplannings\nPompiers /\nSAMU\nInterventions d'urgence Caserne, formation,\ngestion du matériel\nMilitaire Combat, opérations Entraînement, vie de\ngarnison, doctrine\nLe principe est simple : hiérarchie pour la SÉCURITÉ, autonomie pour\nTOUT LE RESTE.\nCe n'est pas un compromis mou. C'est une position intellectuellement\nhonnête. Et c'est celle qui a le plus de chances de convaincre, parce qu'elle\nne nie pas la réalité.\n154",
