      "pageNumber": 159,
      "text": "slides. Vous faites votre métier. Le métier que vous avez choisi. Le métier\nque vous aimez.\n12h00. Déjeuner. Avec tout le monde. Pas de cantine séparée pour les\ncadres. Pas de restaurant privé pour les dirigeants. La même table. Les\nmêmes plats. Les mêmes conversations.\n14h00. Réunion d'équipe mensuelle. Celle-ci est importante. On y discute :\nles résultats du mois, les problèmes rencontrés, les idées d'amélioration.\nTout le monde parle. Tout le monde vote. Les décisions sont prises par\nceux qui les appliqueront — pas par quelqu'un qui ne sera pas là pour en\nvoir les conséquences.\n16h30. Vous avez une idée. Une amélioration technique, un nouveau\nprocédé, un outil qui ferait gagner du temps à tout le monde. Vous en\nparlez à l'équipe. On essaie. Si ça marche, on l'adopte. Personne n'a besoin\nde \"valider en comité\". Personne n'attend six mois pour un \"retour de la\ndirection\".\n17h00. Vous partez. Sans culpabilité. Parce que le travail est fait, et que\nvotre vie ne se réduit pas à votre travail.\nLes principes du monde d'après\nCe lundi n'est pas un fantasme. Chacun de ses éléments existe déjà quelque\npart dans le monde (on l'a vu au chapitre précédent). Ce qui manque, c'est\nde les assembler. Voici les principes :\n1. La conﬁance par défaut\nAujourd'hui : on vous surveille et vous devez prouver que vous méritez la\nconfiance. Demain : on vous fait confiance et vous prouvez, par votre\ntravail, que c'est mérité.\nC'est un renversement de la charge de la preuve. Au lieu de présumer que\nles gens tricheront si on ne les contrôle pas, on présume qu'ils feront bien\n158",
