      "pageNumber": 164,
      "text": "▌  VOIX DU TERRAIN\n« Dans notre coopérative, on a instauré la transparence totale des\nsalaires il y a cinq ans. Les premiers mois ont été tendus. Puis les gens\nont compris que la transparence protège tout le monde. Plus de\nfavoritisme. Plus de suspicion. Plus de rumeur. Juste des faits. »\n— Associé-salarié, SCOP numérique, Lyon\n« J'enseigne en primaire. J'ai arrêté de noter mes élèves il y a trois ans.\nAu début, les parents paniquaient. \"Comment on sait s'il est bon ?\" Je\nleur réponds : \"Vous le savez parce qu'il est heureux d'apprendre.\" C'est\nla seule note qui compte. »\n— Institutrice, école publique, Tarn\n« J'ai utilisé l'IA pour automatiser 80 % de mon reporting. Mon\nmanager m'a dit d'arrêter — parce que si le reporting se fait tout seul,\n\"on ne justifie plus les effectifs du service.\" L'IA aurait pu me libérer.\nMon manager a préféré me garder enchaîné. »\n— Contrôleur de gestion, groupe agroalimentaire\n« Quand on a supprimé le poste de chef de rayon et qu'on a laissé\nl'équipe s'auto-organiser, la productivité a augmenté de 20 % en trois\nmois. Mais la direction a rétabli le poste six mois plus tard. Raison\nofficielle : \"il faut un interlocuteur identifié\". Raison réelle : un chef de\nrayon justifie un directeur de magasin qui justifie un directeur régional.\nSans la base, tout l'édifice s'effondre. »\n— Employé de grande distribution, Normandie\n163",
