      "text": "LE MOT DE L'AUTEUR\nCe livre est un objet libre, déposé ici en toute simplicité.\nIl n'a pas été écrit pour juger, diviser ou viser qui que ce soit. C'est\nsimplement une exploration humaine et lucide du travail, de ses rouages\ninvisibles et des distances qui s'installent parfois entre les étages d'une\norganisation.\nPrenez-le, parcourez-en quelques pages pendant votre pause, et si le\ncœur vous en dit, rejoignez l'échange avant de le faire circuler.\n▌  L'AGORA DES 9 ÉTAGES\nÀ quel étage vous sentez-vous aujourd'hui ?\nScannez ce QR Code avec votre smartphone pour\naccéder à l'Agora, lire les témoignages de vos collègues\net partager votre propre réalité en toute liberté et\nanonymat.\n168",
