      "text": "PROLOGUE SOMMET : DEMAIN,\nVOTRE TERRAIN NE VIENT PAS.\nQuatre lieux. Quatre métiers. Le même lundi matin.\nMais cette fois, personne ne monte de l'étage 0.\nLIEU 1 — Un théâtre, quelque part.\n8h15. Le directeur de salle arrive. Café en main. Badge au cou. Il\nouvre son ordinateur, consulte ses mails, prépare la réunion de 10h\navec le programmateur.\nÀ 9h00, il descend vers le plateau. Les portes sont ouvertes. Les\nlumières sont éteintes. La console est froide. Les perches n'ont pas\nbougé. Le sol n'a pas été balayé.\nPersonne.\nIl appelle. Pas de réponse. Le régisseur ne viendra pas. Les\ntechniciens ne viendront pas. L'habilleuse ne viendra pas.\nL'accessoiriste ne viendra pas.\nIl est 9h30. Dans une heure, trois cents personnes vont s'asseoir\ndans cette salle et attendre qu'on leur raconte une histoire. Ils ont\npayé pour ça. Certains ont économisé pour être là.\nLe directeur regarde le plateau vide. Il sait allumer son ordinateur. Il\nsait écrire un budget. Il sait négocier avec une mairie.\nIl ne sait pas allumer un projecteur.\nLe spectacle n'aura pas lieu.\n2",
