      "text": "LIEU 2 — Un service hospitalier, ailleurs.\n7h00. La cadre de santé arrive. Elle est revenue de sa formation sur\n«  le pilotage de la performance soignante  ». Elle a un nouveau\nPowerPoint. Des indicateurs. Un plan d'action.\nElle pousse la porte du service. Les couloirs sont vides. Pas\nd'infirmières. Pas d'aides-soignantes. Pas de brancardiers.\nChambre 12 — surveillance renforcée. Personne ne surveille.\nChambre 7 — perfusion à changer à 9h. Personne ne la changera.\nLa cadre de santé a un master en management de la santé. Elle sait\npiloter un budget. Elle sait remplir un reporting pour l'ARS. Elle sait\nrédiger une fiche de poste.\nElle ne sait plus poser une perfusion.\nLes alarmes commencent à sonner. L'hôpital ne fonctionne pas.\nLIEU 3 — Un restaurant, en centre-ville.\n9h30. Le directeur régional fait son audit terrain. Il arrive avec sa\ngrille d'évaluation, son stylo quatre couleurs et son œil pour les\ndétails.\nLa porte est fermée.\nPas de chef en cuisine. Pas de commis. Pas de plongeur. Pas de\nserveur.\nLes livraisons du matin sont posées devant la porte. Les caisses de\nlégumes chauffent au soleil. Le lot de poisson que quelqu'un aurait\ndû refuser commence à sentir.\n3",
