      "text": "Le directeur régional sait analyser un ticket moyen. Il sait calculer un\nratio matière. Il sait comparer la performance de vingt restaurants\nsur un tableur.\nIl ne sait pas faire une omelette.\nLe restaurant n'ouvrira pas aujourd'hui.\nLIEU 4 — Un chantier, en banlieue.\n7h30. Le conducteur de travaux revient de sa réunion avec le maître\nd'ouvrage. Tableaux Excel, pourcentages d'avancement, marges\nprévisionnelles — tout est prêt. Il a même préparé un diagramme de\nGantt.\nLe chantier est silencieux.\nPas de chef d'équipe. Pas de ferrailleur. Pas de grutier. Pas de\nmaçon. La grue ne tourne pas. Le béton n'est pas commandé. La\ndalle ne sera pas coulée.\nLe conducteur de travaux sait lire un plan. Il sait planifier un\nchantier. Il sait négocier un avenant.\nIl ne sait pas couler une dalle.\nLe chantier n'avancera pas d'un centimètre.\nQuatre endroits. Quatre métiers. Quatre équipes\nterrain absentes.\nArrêt total.\nPosez-vous la question. Pas pour ces gens-là. Pour vous.\n4",
