      "pageNumber": 6,
      "text": "Si demain, les gens « d'en bas » ne viennent pas — est-ce que ça\ncontinue ?\nOu est-ce que tout s'arrête ?\nEt si tout s'arrête...\nAlors qui fait vraiment tourner le monde ?\nCe n'est pas une attaque. C'est un miroir.\nDe l'autre côté de ce livre — si vous le retournez — il y a le même\nlundi matin. Les mêmes quatre lieux. Mais là-bas, c'est le manager\nqui ne vient pas. Et le spectacle a lieu. L'hôpital soigne. Le restaurant\nsert. Le chantier avance.\nSans un accroc.\nLa question n'est pas de savoir si le management est utile. Bien sûr\nqu'il l'est — ou qu'il peut l'être.\nLa question est plus simple, et plus vertigineuse :\nSi le terrain peut tourner sans vous, mais que vous ne pouvez rien\nfaire tourner sans le terrain — qui tient vraiment le pouvoir ?\nEt si la réponse vous met mal à l'aise — alors peut-être que ce livre\nest pour vous.\nDescendons.\n5",
