      "text": "ÉTAGE 8 — LE CEO\n▲▼ ■ ■ ■ ■ ■ ■ ■ ■ ■ ÉTAGE 8 SUR 9 · DÉPART DU SOMMET\nCelui qui signe — et qui ne sait plus quoi.\nCe chapitre est court. Comme les journées du CEO sont longues,\nmais vides de ce qui compte.\nLe bureau est immense. Baie vitrée. Skyline. Un horizon qui n'en\nfinit pas.\n164 000 personnes travaillent sous cette signature. 164 000 vies. 164\n000 réveils à 5h du matin, 164 000 trajets dans le froid, 164 000\npaires de mains qui font le travail que le monde consomme.\nIl ne les verra jamais.\nCe matin, le CEO a un rapport trimestriel sur son bureau. 247 pages.\nDes graphiques. Des tendances. Des projections. Tout est codé en\ncouleurs — vert, orange, rouge — comme si la réalité pouvait tenir\ndans un feu tricolore.\nIl tourne les pages. Revenus en hausse de 3,2 %. EBITDA stable.\nCoûts de personnel « maîtrisés » — un euphémisme pour dire qu'on\na gelé les embauches et laissé partir les CDD.\nUne phrase l'arrête, au milieu d'un graphique : « Taux de turnover\nétage 0 : +17 % sur l'exercice. »\n6",
