      "pageNumber": 8,
      "text": "Il souligne le chiffre. Note dans la marge : « Voir avec RH. »\nPuis il tourne la page.\nIl y a dix-huit mois, il a visité un site de production. C'était organisé.\nLe directeur l'avait prévenu trois semaines à l'avance. Les allées\nétaient propres. Les gens souriaient. On lui a fait visiter l'atelier le\nplus récent, celui avec les machines neuves. On a soigneusement\névité le bâtiment B, celui où le chauffage ne fonctionne plus depuis\ndeux hivers.\nIl est reparti en disant  : «  Impressionnant. Les équipes sont\nformidables. »\nIl le pensait sincèrement.\nIl ne savait pas qu'on lui avait montré un décor.\nCe soir, dans la voiture qui le ramène chez lui — une berline noire,\nvitres teintées, un silence parfait —, une pensée lui traverse l'esprit.\nElle est brève. Presque rien. Mais elle est là :\n« Est-ce que je sais vraiment ce qu'on fait ? »\nPas ce que l'entreprise produit. Il connaît le discours. La mission. La\nvision. Les valeurs — il les a lui-même approuvées, encadrées,\naccrochées dans le hall d'entrée.\nMais ce qu'on fait. Concrètement. Avec les mains. Le geste\ntechnique. Le savoir-faire. Le produit tel qu'il naît, avant qu'il ne\ndevienne un chiffre dans un rapport trimestriel.\nLa pensée dure trois secondes.\n7",
