      "pageNumber": 12,
      "text": "ÉTAGE 7 — LE CHAIRMAN\n▲▼ ■ ■ ■ ■ ■ ■ ■ ■ □ ÉTAGE 7 SUR 9 · DESCENTE EN COURS\nCelui qui a commencé en bas — et qui ne reconnaît\nplus le haut.\nIl y a trente ans, il portait un bleu de travail.\nTrente ans. Trois décennies. Le temps qu'il faut pour oublier. Non —\npas oublier. Pour que le souvenir devienne si lointain qu'il ressemble\nà un film vu enfant, dont on ne sait plus si on l'a vraiment vécu ou si\non l'a inventé.\nIl se souvient de l'odeur. C'est toujours l'odeur qui reste le plus\nlongtemps. L'atelier sentait le métal chaud, la graisse, la sciure. Il\narrivait à 6h30. Il posait sa veste sur un crochet. Il enfilait ses gants.\nEt il travaillait.\nLe travail avait une forme. Un début, un milieu, une fin. Le matin, la\npièce était brute. Le soir, elle était terminée. On pouvait la toucher,\nla retourner, la montrer. Ça, c'est moi qui l'ai fait. Il y avait une fierté\nlà-dedans — simple, directe, impossible à simuler.\nAujourd'hui, son bureau est au trente-deuxième étage d'une tour de\nverre. Il ne sent plus rien. L'air est filtré, climatisé, parfumé. Ses\nmains ne touchent plus que des claviers, des stylos Montblanc, et des\npoignées de main calibrées.\n11",
