      "text": "Ce sont des lignes.\nEt les lignes, ça ne sent pas la graisse et la sciure.\n▌  VOIX DU SOMMET\n« Quand j'ai commencé, je me suis juré de ne jamais oublier d'où\nje venais. Je le pensais. Je le pensais vraiment. Aujourd'hui, j'ai\nun chauffeur. Un assistant. Un agenda géré par quelqu'un\nd'autre. Je mange dans des restaurants que je n'aurais jamais pu\nm'offrir à vingt ans. Et l'autre jour, quelqu'un m'a demandé :\n\"Vous avez déjà travaillé sur le terrain ?\" — j'ai répondu oui, mais\nj'ai entendu le doute dans leur voix. Et honnêtement, je ne peux\npas leur en vouloir. Si je me regardais, moi non plus je n'y\ncroirais pas. »\n— Chairman, groupe industriel, en fin de carrière\n13",
