      "text": "▌  LA QUESTION\nIl y a une phrase qu'on entend souvent dans les discours de\ndirigeants qui ont « commencé en bas » :\n« Je n'ai jamais oublié d'où je viens. »\nVraiment ?\nQuand avez-vous parlé pour la dernière fois avec quelqu'un qui\nfait le métier que vous faisiez ? Quand avez-vous touché la\nmatière, senti l'odeur, entendu le bruit ? Quand avez-vous déjeuné\navec quelqu'un qui gagne en un mois ce que vous gagnez en une\nheure ?\nSi la réponse est « je ne sais plus » — alors vous avez oublié.\nCe n'est pas un reproche. C'est un constat. La tour est ainsi faite :\nelle efface le souvenir en même temps qu'elle vous élève.\nMais le souvenir est encore là. Quelque part. Sous les costumes et\nles signatures.\nIl suffirait de redescendre un étage pour le retrouver.\nProchain étage — Le Président International. Celui qui ne dort plus.\n15",
