      "text": "ÉTAGE 6 — LE PRÉSIDENT\nINTERNATIONAL\n▲▼ ■ ■ ■ ■ ■ ■ ■ □ □ ÉTAGE 6 SUR 9 · DESCENTE EN COURS\nCelui qui gère des fuseaux horaires — et qui a perdu\nle sien.\n3h17 du matin.\nChambre 412 d'un hôtel à Singapour. Ou Shanghai. Ou São Paulo. Il\nne sait plus très bien. Les chambres d'hôtel cinq étoiles se\nressemblent toutes — même moquette épaisse, même minibar,\nmême silence ouaté, même solitude.\nSon corps est à Singapour. Son esprit est encore à Paris. Son agenda\nest déjà à New York.\nLe jet lag n'est plus un inconvénient. C'est un état permanent.\nIl se lève. Il ouvre son ordinateur. 83 mails reçus pendant qu'il ne\ndormait pas. Il ne dormait pas, mais il ne travaillait pas non plus. Il\nétait dans ce no man's land que connaissent tous les gens qui vivent\ndans les avions — trop fatigué pour dormir, trop décalé pour être\nlucide.\nIl scrolle les mails. Japon : les résultats du T2 sont en dessous des\nattentes. Brésil : un conflit social sur le site de production. Europe :\n16",
