      "text": "le board veut un plan d'économies. Chine  : un problème\nréglementaire.\nChaque pays est un problème. Chaque problème est un fichier.\nChaque fichier est un tableau. Chaque tableau est un chiffre.\nIl ne sait pas à quoi ressemble le site de production au Brésil. Il n'y a\njamais mis les pieds. Il sait que c'est un « marché en croissance »\navec un « P&L prometteur ». Il sait que le headcount est de 3 200\npersonnes. Il ne sait pas ce que ces 3 200 personnes font de leurs\njournées, comment elles viennent au travail, si elles mangent à la\ncantine, si elles ont peur de perdre leur emploi.\n3 200 personnes. Un chiffre dans une cellule Excel. Taille de police :\n10.\nCe soir — ou ce matin, il ne sait plus —, il a un dîner avec un ministre\ndu commerce d'un pays dont il ne parle pas la langue. Un interprète\nsera là. On parlera de « partenariats stratégiques » et de « synergies\nrégionales  ». On se serrera la main pour les photographes. On\nsignera peut-être un protocole d'accord qui ne changera rien à la vie\nde personne à l'étage 0.\nPuis il reprendra l'avion.\nIl ferme l'ordinateur. La ville brille à travers la baie vitrée. Des\nmillions de gens dorment en dessous. Des millions de gens qui se\nlèveront dans quelques heures et iront travailler — dans des cuisines,\ndes hôpitaux, des chantiers, des ateliers, des théâtres.\nIl se pose une question qu'il n'a jamais posée en réunion, qu'il n'a\njamais écrite dans un mail, qu'il n'a jamais murmurée à personne :\n17",
