      "pageNumber": 19,
      "text": "« Qui est-ce que je manage ? »\nPas des marchés. Pas des P&L. Pas des régions.\nDes gens.\nEst-ce qu'il manage des gens ?\nIl ne saurait pas les reconnaître dans la rue. Il ne parle pas leur\nlangue. Il ne connaît pas leurs prénoms, leurs horaires, leurs\ninquiétudes, leur fatigue.\n« Je manage 23 000 personnes dans 14 pays. Et je ne pourrais\npas en nommer une seule. »\nLa ville brille. Le minibar ronronne. Le silence est parfait.\nIl ne se rendort pas.\n▌  VOIX DU SOMMET\n« Ma fille a neuf ans. L'autre jour, elle m'a demandé : \"Papa, c'est\nquoi ton travail ?\" J'ai commencé à expliquer. J'ai dit : \"Je\nm'occupe de plusieurs pays pour l'entreprise.\" Elle m'a regardé et\nelle a dit : \"Mais tu t'occupes de quoi dans les pays ?\" J'ai ouvert\nla bouche. Et je n'ai pas su quoi répondre. Pas parce que c'est\ncompliqué. Parce que, formulé simplement, ce que je fais n'a pas\nde forme. C'est du vent organisé en tableaux. »\n— Président zone internationale, conglomérat\n18",
