      "text": "▌  LA QUESTION\nLes fuseaux horaires sont une métaphore presque trop parfaite.\nPlus vous montez dans la tour, plus vous êtes décalé. Décalé par\nrapport au temps des autres. Décalé par rapport à leur réalité.\nDécalé par rapport à leur vie.\nVous gérez 23 000 personnes. Combien pourriez-vous regarder\ndans les yeux ?\nPas sur un écran. Pas sur une photo dans le rapport annuel. Dans\nles yeux.\nSi la réponse est un nombre à un chiffre — alors le mot « gérer »\nne veut plus dire ce que vous croyez.\nProchain étage — Le Président de Division. Celui qui parle — et qui\nn'entend pas.\n20",
