      "text": "Les 241 autres questions — celles sur les salaires, les sous-effectifs,\nles promotions bloquées, le chauffage du bâtiment B, les CDD non\nrenouvelés, les cadences, la souffrance — sont dans un fichier que\npersonne ne lui montrera.\nIl ne sait pas.\nOu peut-être qu'il sait. Peut-être qu'il sait sans savoir. Peut-être qu'il\npréfère ne pas demander. Peut-être que c'est plus confortable de\ncroire que 6 questions sur 247 représentent la réalité.\nIl monte sur scène.\n« Bonjour à toutes et à tous. »\nLa salle est à moitié pleine. Pas parce que les gens ne veulent pas\nvenir — mais parce que les plannings de l'étage 0 ne permettent pas\nde libérer tout le monde en même temps. Ceux qui sont là ont été\n« désignés ». Certains auraient préféré continuer à travailler.\nIl ne le sait pas.\n« Je voulais prendre ce moment pour vous dire une chose que je\npense profondément... »\nIl regarde la salle. Il cherche les visages. Il veut du contact. Il est\nsincère — c'est ça le plus troublant. Il est sincère.\n« Vous êtes notre plus grande richesse. »\nSilence dans la salle.\nPas un silence hostile. Pas un silence ému. Un silence usé. Le silence\nde gens qui ont entendu cette phrase trop souvent, prononcée par\ntrop de gens, suivie de trop peu d'effets.\n22",
