      "text": "Au troisième rang, un technicien regarde ses chaussures. Il pense à\nson contrat. Il est en CDD depuis quatre ans. Quatre CDD successifs.\nQuatre fois la promesse d'un CDI. Quatre fois le renouvellement.\nVous êtes notre plus grande richesse.\nAu dixième rang, une infirmière vérifie son téléphone. Elle a laissé le\nservice en sous-effectif pour être là. Sa collègue gère seule treize\npatients.\nVous êtes notre plus grande richesse.\nAu fond de la salle, un chef d'équipe est déjà parti. Il a un problème à\nrégler sur le terrain. Un vrai problème. Pas un problème de slides.\nIl fait son discours. Il le fait bien. Il y met de l'énergie, de la\nconviction. Il parle de vision, de valeurs, d'avenir. Il montre les\nvidéos. Les gens applaudissent poliment.\nPuis viennent les questions. Les six questions. Il y répond avec\naisance. Il est bon dans cet exercice. Trente ans de carrière. Des\ncentaines de prises de parole.\nLa question qu'il ne recevra pas, celle qui dort dans le fichier des\n241 :\n« Si nous sommes votre plus grande richesse, pourquoi est-ce que\nnos salaires n'ont pas bougé en trois ans alors que les vôtres ont\naugmenté de 40 % ? »\nAprès le Town Hall, il remonte dans son bureau. Il est satisfait. « Ça\ns'est bien passé », dit-il à son assistante. Et c'est vrai — dans le cadre\nde ce qui lui a été montré, ça s'est bien passé.\n23",
