      "text": "▌  LA QUESTION\nCombien de vérités peut-on entendre quand tout le monde autour\nde soi a intérêt à mentir ?\nCe n'est pas de la conspiration. Personne ne complote.\nL'assistante est gentille. Le dircom fait son travail. Le DRH\nprotège l'organisation.\nMais le résultat est le même : vous vivez dans une version filtrée\ndu réel.\nChaque étage que vous avez gravi a ajouté un filtre. Un filtre de\nplus entre vous et la vérité. Aujourd'hui, à l'étage 5, il y a cinq\nfiltres entre vous et la réalité.\nCinq personnes qui décident, avant vous, ce que vous avez le droit\nde savoir.\nLa question n'est pas : « Est-ce qu'on me ment ? »\nLa question est : « Est-ce que je veux vraiment savoir ? »\nEt si oui — il va falloir descendre plus bas qu'un Town Hall.\nProchain étage — Le Vice-Président. Celui qui gère le budget — et qui\ndécouvre ce que « couper » veut dire en vrai.\n26",
