      "pageNumber": 32,
      "text": "Ce que contient une signature\nPrenons un exemple concret. Un plan de réduction des coûts, baptisé\n« Projet Horizon ». Comme toujours, le nom est beau. Lumineux.\nTourné vers l'avenir. Les projets qui font mal portent toujours des\nnoms qui font rêver.\nLe document fait 47 pages. Marc-Antoine en lit 12 — le résumé\nexécutif, les projections financières, la matrice de risques. Il ne lit\npas les annexes. Personne ne lit les annexes. C'est dans les annexes\nque se trouvent les postes supprimés. Les sites concernés. Les\nfonctions « rationalisées ».\nIl signe.\nDans les annexes qu'il n'a pas lues, il y a :\n34 postes supprimés sur le site de Rouen.\nLa fermeture d'un service client de proximité qui existait\ndepuis 22 ans.\nLe non-renouvellement de 12 CDD, dont celui de Nadia, 28\nans, qui venait d'acheter sa première voiture pour venir\ntravailler.\nLa fusion de deux équipes qui ne se parlent pas, qui ne font\npas le même métier, mais qui, sur un organigramme, occupent\ndes cases adjacentes.\nMarc-Antoine ne connaît pas Nadia. Il ne connaîtra jamais Nadia. Et\nc'est exactement le problème.\nLa distance comme anesthésie\nIl y a une relation directe entre la distance hiérarchique et la capacité\nà prendre des décisions douloureuses. Ce n'est pas un bug du\n31",
