      "pageNumber": 35,
      "text": "Ce qu'il a fait de ce qu'il a vu\nRien.\nIl n'a rien fait.\nC'est la vérité, et elle est importante. Parce que la prise de\nconscience, sans le pouvoir d'agir, c'est juste de la souffrance\nsupplémentaire. Et Marc-Antoine n'avait pas le pouvoir d'agir. Pas\nvraiment. Pas dans les structures telles qu'elles existent.\nIl a essayé. Il a mentionné, dans un comité de direction, que « les\néquipes terrain vivent mal la transformation ». On lui a répondu :\n« C'est normal, c'est la courbe du changement. Phase 2 : résistance.\nÇa passera. »\nIl a essayé de ralentir le prochain plan. On lui a répondu que les\nobjectifs étaient « non-négociables » et que « le marché n'attend\npas ».\nIl a essayé de visiter plus souvent. Son agenda ne le permettait pas.\nTrois jours par semaine à Paris, un jour en visio avec l'international,\net le vendredi pour les « sujets RH », c'est-à-dire les PowerPoints sur\nles sujets RH.\nAlors il a continué à signer.\nLe soir\nLe soir, Marc-Antoine rentre chez lui. Banlieue ouest, maison avec\njardin, deux enfants qui grandissent sans faire trop de bruit. Sa\nfemme, Sophie, est architecte. Elle a son propre monde, ses propres\nbatailles.\n34",
