      "text": "ÉTAGE 3 — LE DIRECTEUR\n▲▼ ■ ■ ■ ■ □ □ □ □ □ ÉTAGE 3 SUR 9 · DESCENTE EN COURS\nCelui qui revient sur le terrain\n▌  VOIX DU SOMMET\n« Quand j'étais sur le terrain, je détestais les directeurs qui\npassaient dans l'atelier sans nous saluer. Aujourd'hui, je suis ce\ndirecteur. Je passe vite dans les couloirs, le regard fixé sur mon\nécran, parce que si je m'arrête, je sais qu'on va me poser des\nquestions auxquelles mon budget ne me permet pas de répondre.\nAlors je reste au 3e étage. Et je pilote un site que je ne regarde\nplus. »\n39",
