      "text": "▌  LE TRADUCTEUR DU SOMMET\nCe que le\nDirecteur dit en\nréunion\nCe qu'il pense\nvraiment\nCe que le Terrain\ncomprend\n« Nous devons\noptimiser nos flux\npour rester\ncompétitifs. »\n« Le siège me\ndemande 5 %\nd'économies, je ne\nsais pas où couper. »\n« Ils vont encore\nsupprimer des\npostes et nous\ndemander d'en faire\nplus. »\n« Ma porte est\ntoujours ouverte. »\n« Venez avec des\nsolutions, pas avec\ndes problèmes que je\nne peux pas payer. »\n« Ne viens surtout\npas me déranger\navec tes galères du\nquotidien. »\n« C'est un problème\nde communication\ninterne. »\n« Les équipes n'ont\npas compris pourquoi\non leur impose ça. »\n« C'est de votre faute\nsi vous n'êtes pas\ncontents. »\n▌  LA QUESTION\nLa question que le Directeur n'ose jamais poser au\nTerrain :\n« Si je descendais passer une journée entière avec vous, sans\ncravate et sans carnet de notes... auriez-vous le courage de me\ndire tout ce qui ne va pas, et aurais-je le courage de vous\nécouter ? »\n41",
