      "pageNumber": 43,
      "text": "7h45\nLe parking est presque vide à cette heure-là.\nLaurent gare sa voiture au fond, loin de l'entrée principale, là où les\nplaces n'ont pas de numéro. Les places numérotées — celles\nréservées aux directeurs, près de la porte, à l'abri du vent — sont\ntoutes libres. Normal  : les directeurs arrivent entre 9h et 9h30.\nLaurent le sait. Il est l'un d'eux.\nMais pas aujourd'hui.\nAujourd'hui, il est arrivé à 7h45. Il ne sait pas exactement pourquoi.\nC'est-à-dire qu'il le sait, quelque part, mais il ne se l'est pas encore\nformulé en mots. C'est venu comme ça, dans la nuit, entre deux\nréveils. L'idée de venir tôt. De venir avant. Avant les réunions, avant\nles mails, avant le bruit du management. De venir au moment où\nl'entreprise existe sans lui. Où elle fonctionne — ou pas —\nindépendamment de ses décisions, de ses validations, de ses\n« arbitrages ».\nIl coupe le moteur. Reste assis un moment. Regarde le bâtiment.\nIl y travaille depuis sept ans. Directeur de site depuis trois ans.\nAvant, il était Responsable Production. Avant encore, il était\ningénieur process. Il a commencé ici. Dans ce bâtiment. Au rez-de-\nchaussée. Il connaissait le bruit des machines, l'odeur de la graisse\nchaude, la texture des gants de protection. Tout ça semble si loin\nmaintenant. Comme une autre vie vécue par quelqu'un d'autre.\nIl sort de la voiture.\n42",
