      "pageNumber": 44,
      "text": "L'entrée\nIl entre par la porte latérale, celle que les équipes du matin utilisent.\nPas par l'accueil principal avec les fauteuils design et la plante verte\nque personne n'arrose. La porte latérale qui grince. Qui a toujours\ngrincé. Qui grincera toujours, parce que personne n'a le budget pour\nla changer et parce que personne dans son bureau n'a jamais utilisé\ncette porte.\nLe couloir sent le café de machine et le produit d'entretien. Le sol est\nun peu collant par endroits. Les néons sont blancs, durs, sans\nnuance. Rien à voir avec les spots orientables de son bureau du 3e\nétage.\nLaurent marche. Il ne s'annonce pas. Il n'a prévenu personne. Il\nporte un jean et un pull — pas de costume, pas de badge\n« Direction » visible. Il veut voir. Juste voir.\nCe qu'il voit\n7h52 — L'atelier\nL'équipe du matin est déjà en place. Six personnes autour d'une table\nhaute, debout, café à la main. Briefing du jour. Celui qui parle, c'est\nKarim, le chef d'équipe. Il ne lit pas un document. Il n'a pas de\nslides. Il raconte  : ce qui s'est passé hier soir, ce qui est prévu\naujourd'hui, qui est absent (Sandrine, son fils est malade), qui prend\nle relais (Moussa, il a déjà vu avec elle par texto).\nC'est fluide. C'est rapide. C'est efficace.\nLaurent réalise que ce briefing n'a rien à voir avec les « rituels de\nmanagement » qu'il prescrit dans ses notes de cadrage. Pas de « tour\nde table structuré ». Pas de « KPI du jour ». Pas de « point sécurité\n43",
