      "text": "parle de « prise de conscience ». De « moment de lucidité ». De\n« remise en question ». Mais le mot, c'est la honte.\nLa honte de ne pas avoir vu. De ne pas être venu plus tôt. De s'être\nlaissé absorber par les réunions, les comités, les reportings — tout\ncet appareillage managérial qui donne l'impression de travailler sans\njamais toucher le réel.\nL'admiration aussi. C'est l'autre sentiment, et il arrive juste après,\ncomme un contrepoint. L'admiration pour Karim qui tient son\néquipe avec une autorité naturelle qu'aucune formation au\nleadership ne pourra jamais enseigner. Pour Youssef qui a construit\nun outil plus efficace que celui à 2,3 millions. Pour Fatima qui jongle\nentre deux systèmes sans jamais se tromper. Pour tous ces gens qui\nfont tourner la machine chaque jour, malgré la clim en panne,\nmalgré les logiciels inadaptés, malgré le silence d'en haut.\nEt la confusion. Parce que Laurent ne sait pas quoi faire de tout ça. Il\nest directeur de site. Il est responsable de ce site. Et il vient de\ndécouvrir qu'il ne le connaît pas. Que la carte qu'il a —\nl'organigramme, les processus, les indicateurs — ne correspond pas\nau territoire. Que le territoire est plus riche, plus complexe, plus\nintelligent que tout ce qu'il avait imaginé depuis son bureau.\nLa pause déjeuner\nLaurent décide de manger au self. Il n'y a pas mis les pieds depuis...\nil ne se souvient plus. Longtemps. D'habitude, il déjeune dans son\nbureau (un sandwich), ou à l'extérieur avec des clients ou des\nhomologues.\nLe self est bruyant. Il y a du monde. Des gens en blouse, d'autres en\njean, certains en tenue de sécurité. Ça sent les frites et la sauce\n47",
