      "text": "tomate. Les plateaux sont en plastique beige, légèrement rayés. Les\ntables sont grandes, collectives, sans place attribuée.\nLaurent s'assoit au bout d'une table. À côté de lui, un homme d'une\ncinquantaine d'années, lunettes, les mains marquées — les mains de\nquelqu'un qui travaille. C'est Patrick. Technicien de maintenance. 28\nans d'ancienneté. Autant dire qu'il a vu passer six directeurs de site,\ndont Laurent.\nLa conversation commence par le plateau.\n— Le poisson, c'est mieux le jeudi, dit Patrick. Le mercredi, faut pas\ntenter.\nLaurent sourit. Ils parlent de la cantine. Puis du temps qu'il fait.\nPuis, progressivement, comme un fleuve qui s'élargit sans qu'on s'en\naperçoive, ils parlent du travail.\nPatrick parle calmement. Sans colère. Sans amertume non plus —\nenfin, pas beaucoup. Il parle comme quelqu'un qui a fait le deuil de\nses illusions mais qui n'a pas perdu sa lucidité.\n— Le truc, dit Patrick, c'est que vous — enfin, la direction — vous\npensez qu'on résiste au changement. Mais c'est pas ça. On change\ntout le temps. Tous les jours, on s'adapte. Quand le logiciel plante,\non s'adapte. Quand un collègue part et qu'on le remplace pas, on\ns'adapte. Quand la procédure dit un truc et que la réalité en dit un\nautre, on s'adapte.\nIl pose sa fourchette.\n— Ce qu'on supporte pas, c'est de changer pour rien. Pour un\nPowerPoint. Pour un nouveau directeur qui veut «  marquer son\n48",
