      "pageNumber": 51,
      "text": "Le retour au bureau\n14h30. Laurent est de retour au 3e étage. La moquette est épaisse.\nL'air est frais. L'écran affiche 47 mails non lus. Son assistante lui\nrappelle qu'il a un call à 15h avec le groupe.\nIl s'assoit dans son fauteuil. Ferme les yeux une seconde.\nEt maintenant ?\nC'est la question la plus difficile. Parce que voir ne suffit pas. Savoir\nne suffit pas. La question, c'est : qu'est-ce qu'on fait de ce qu'on sait ?\nLaurent ouvre un document vide. Il commence à écrire. Pas un plan\nstratégique. Pas une note de cadrage. Juste des mots. Des choses\nqu'il a vues. Des choses qu'il a entendues. Des choses qu'il veut\nchanger.\nIl écrit :\nFaire réparer la clim. Cette semaine. Pas le prochain cycle\nbudgétaire. Cette semaine.\nRencontrer Youssef. Voir son application. Comprendre ce\nqu'elle fait que notre logiciel à 2,3M ne fait pas.\nLire les 47 idées du panneau. Toutes. Répondre à chacune.\nMême si la réponse est non, expliquer pourquoi.\nRevenir déjeuner au self. Pas une fois. Régulièrement. Comme\nun rituel. Comme un devoir.\nParler à Patrick. Lui proposer... quoi ? Je ne sais pas encore.\nMais lui parler.\nIl regarde sa liste. Elle est modeste. Dérisoire, même, comparée à\nl'ampleur de ce qu'il a vu. Mais elle est concrète. Elle est faisable. Et\n50",
