      "pageNumber": 52,
      "text": "surtout, elle est décidée. Pas « soumise à validation ». Pas « intégrée\ndans la roadmap ». Décidée. Par lui. Maintenant.\nIl imprime la liste. La plie. La met dans sa poche.\nLe call de 15h commence. On parle de « synergies transverses » et\nd'« efficience opérationnelle ». Laurent écoute. Mais dans sa poche,\nil y a un papier plié qui pèse plus lourd que toute la réunion.\nL'après\nDeux semaines plus tard, la climatisation est réparée.\nCe n'était pas compliqué. Ce n'était pas cher. C'était juste oublié.\nPerdu dans les méandres d'un processus d'approbation conçu pour\ndes investissements de plusieurs millions, mais qui traitait une\npanne de clim comme un projet d'infrastructure.\nLaurent a simplement appelé le prestataire et dit : « C'est urgent,\nfaites-le. » Et c'était fait.\nIl a rencontré Youssef. Ils ont passé une heure ensemble. Laurent a\nappris plus sur les besoins réels du terrain en une heure qu'en trois\nans de comités de pilotage IT. L'application de Youssef a été\nofficialisée, documentée, sécurisée — et Youssef a été promu référent\ndigital de l'atelier, un rôle qui n'existait pas et qui existe maintenant.\nIl a répondu aux 47 post-it. Pas par mail. En personne, debout\ndevant le panneau de liège, avec les gens autour. Certaines idées ont\nété retenues. D'autres non, mais il a expliqué pourquoi. Les gens\nn'étaient pas contents de tous les « non ». Mais ils étaient stupéfaits\nqu'on leur ait répondu.\n51",
