      "text": "que vous l'avez vu sur le bureau de quelqu'un d'autre et que le titre\nvous a intrigué.\nVous avez commencé à lire.\nEt votre première réaction a été : C'est exagéré.\nC'est normal. C'est la réaction de tout le monde. Surtout quand on\nest du côté du Sommet. Parce que le livre parle de vous, et personne\nn'aime se reconnaître dans un portrait peu flatteur.\n« C'est caricatural. » Oui, un peu. Comme toute satire, comme tout\nmiroir grossissant. Le miroir grossissant ne montre pas le visage tel\nqu'il est — il montre les pores, les rides, les imperfections qu'on a\nappris à ne plus voir.\n« Mon entreprise n'est pas comme ça. » Peut-être. Peut-être que\nvotre entreprise est différente. Peut-être que chez vous, les décisions\nsont prises en concertation, les équipes sont écoutées, les managers\nde proximité ont les moyens de bien faire leur travail. Si c'est le cas,\ntant mieux. Sincèrement. Ce livre n'a pas été écrit pour les\nentreprises parfaites. Il a été écrit pour les autres — c'est-à-dire pour\nla grande majorité.\n« L'auteur ne connaît pas la réalité du management. » C'est possible.\nMais les gens du terrain, eux, la connaissent. Et quand les mêmes\ntémoignages reviennent partout — dans toutes les entreprises, dans\ntous les secteurs, dans tous les pays —, à un moment, il faut se\ndemander si le problème vient des témoins ou du système.\nVous tournez les pages en fronçant les sourcils. Vous annotez dans la\nmarge : « pas vrai chez nous », « contexte différent », « raccourci\nintellectuel  ». Vous cherchez les failles dans l'argumentation, les\n56",
