      "pageNumber": 58,
      "text": "exceptions qui invalident la règle, les exemples qui ne s'appliquent\npas à votre situation.\nC'est le déni. Et c'est parfaitement humain. On ne lâche pas une\nvision du monde comme ça, entre deux chapitres.\nPhase 2 : La reconnaissance\nElle arrive sans prévenir. Pas comme un éclair. Plutôt comme un\nlever de jour — lent, progressif, impossible à situer avec précision.\nC'est peut-être un passage du chapitre 3 qui vous a fait penser à cette\nréunion, celle de jeudi dernier, où votre N-1 n'a pas osé vous\ncontredire même si vous voyiez dans ses yeux qu'il n'était pas\nd'accord.\nC'est peut-être le chapitre sur les indicateurs qui vous a rappelé ce\ntableau de bord que vous consultez chaque lundi matin — 15 KPI,\ndont 3 que vous comprenez vraiment et 12 que vous faites semblant\nde comprendre.\nC'est peut-être le passage sur les «  décisions prises avant la\nréunion » qui vous a fait repenser à ce comité de direction où tout le\nmonde valide tout, parce que tout a été négocié en coulisses, et que\nla réunion n'est qu'un théâtre.\nOkay, vous vous dites. Peut-être que certaines choses sont vraies.\nPas tout. Mais certaines choses.\nEt cette concession, aussi minime qu'elle paraisse, est un moment\nimmense. Parce qu'elle ouvre une brèche. Et par cette brèche,\nd'autres reconnaissances vont s'engouffrer.\n57",
