      "pageNumber": 66,
      "text": "ÉTAGE 0 — LE RETOUR AU RÉEL\nL'arrivée au sol : là où la fiction s'arrête\n▲▼ ■ □ □ □ □ □ □ □ □ ÉTAGE 0 SUR 9 · ARRIVÉE AU SOL\nLes portes de l'ascenseur s'ouvrent enfin au niveau zéro.\nPendant des années, vous n'avez vu cet étage qu'à travers des\nreportings consolidés, des courbes de productivité, des taux de\nfreinte et des ratios d'accidents du travail. En haut, l'Étage 0 n'était\npas un lieu : c'était une ligne budgétaire.\nMais en franchissant ces portes, le premier choc n'est pas\nmanagérial. Il est sensoriel.\nC'est l'odeur du métal usiné, du café froid dans les gobelets en\ncarton, de la poussière de carton ou du désinfectant hospitalier. C'est\nle bruit continu des machines, les pas pressés, les voix qui\ns'interpellent sans filtre ni politesse de salon.\nIci, la moquette épaisse de l'Étage 8 n'existe pas. Le sol est dur, froid,\nmarqué par le passage des transpalettes et la sueur des équipes.\nLa ﬁn des PowerPoints\nVous regardez autour de vous. Personne ne porte de costume taillé\nsur mesure. Personne ne parle de «  synergies transverses  » ni\n« d'alignement stratégique ».\n65",
