      "text": "▌  VOIX DU SOMMET — AU CONTACT DU SOL\n« Le jour où j'ai passé huit heures complètes à suivre une équipe\nde nuit dans notre plus grand centre de tri, sans escorte RH ni\nphotographe, j'ai eu honte. J'ai compris que les trois quarts de\nmes tableaux de bord mesuraient des futilités, et que la seule vraie\nrichesse de notre boîte tenait dans le courage et la fierté de ces\ngars-là. En rentrant, j'ai annulé deux comités de direction et j'ai\ninvesti directement sur leurs outils. »\n▌  LA QUESTION DU SOL « Si tout votre état-major disparaissait\npendant un mois, l'entreprise continuerait de tourner. Si l'Étage 0\ns'arrêtait demain pendant une heure, que resterait-il de votre\npouvoir ? »\nCelui qui a changé de rive\n▌  VOIX DU SOMMET\n« Je suis monté d'un étage parce qu'on m'a dit que j'allais faire\névoluer les choses. Résultat : je ne fais plus mon métier, je passe\nmes journées à remplir des tableurs de présence, et mes anciens\ncollègues me regardent comme un traître dès que j'entre dans\nl'atelier. Je suis le seul à connaître le travail réel, et je suis le seul\ndont personne n'écoute l'avis. »\n67",
