      "text": "▌  LE TRADUCTEUR DU SOMMET\nCe que le\nManager de\nProximité dit\nCe qu'il pense\nvraiment\nCe que le Terrain\ncomprend\n« C'est une consigne\nqui vient d'en\nhaut. »\n« Je trouve ça aussi\ndébile que vous, mais\nsi je refuse, je saute. »\n« Tu n'as aucun\ncourage pour nous\ndéfendre. »\n« On va faire un\npoint rapide. »\n« Je dois vous\nannoncer une\nmauvaise nouvelle\navant 10h. »\n« Encore une réunion\npour nous faire\nperdre du temps. »\n« Je compte sur\nvotre engagement. »\n« Si les objectifs ne\nsont pas atteints, c'est\nmoi qui prends la\nfoudre. »\n« Tu nous demandes\nde faire des heures\nsup gratuites. »\n▌  LA QUESTION\nLa question que le Manager de Proximité n'ose jamais\nposer :\n« Vous souvenez-vous qu'hier encore, j'étais l'un des vôtres... et\nque si je tiens debout aujourd'hui, c'est uniquement pour vous\néviter le pire ? »\nLa mémoire du corps\nIl y a des choses que le corps se souvient même quand la tête a\noublié.\n69",
