      "pageNumber": 79,
      "text": "— Tiens, tu recommences à parler normal.\nC'est peut-être le plus beau compliment qu'il ait jamais reçu.\nLe soir, en rentrant chez lui, il passe devant l'ancien site où il a\ncommencé sa carrière. Le bâtiment est toujours là. Les fenêtres sont\néclairées. Des gens travaillent. Des gens qu'il ne connaît pas, qui font\nun métier qu'il connaît par cœur.\nIl ralentit. Regarde. Sourit.\nEt dans ce sourire, il y a de la nostalgie, oui. Mais il y a aussi de\nl'espoir. Parce que se souvenir d'où l'on vient, ce n'est pas regarder\nen arrière. C'est savoir d'où on tient sa force. Et cette force-là, aucun\norganigramme ne peut la supprimer.\n78",
