      "text": "La personne. Claire, 48 ans, nommée directrice des opérations après\nune carrière dans l'industrie automobile. Elle arrive avec un constat\nsimple : « Dans mon ancienne entreprise, une idée terrain mettait 14\nmois pour devenir une décision. Ici, c'est combien ? » Personne ne\nsavait répondre. Ce qui était déjà une réponse.\nCe qu'elle a fait. Pas une révolution. Un démontage méthodique. Elle\na commencé par cartographier les flux de décision : qui autorise\nquoi, et combien de temps ça prend. Le résultat était effarant. Pour\ncommander un outil à 50 euros, il fallait trois signatures et cinq\njours. Pour modifier un horaire de pause, il fallait remonter au\ndirecteur de site.\nPuis elle a posé une question à chaque niveau intermédiaire : « Si\nvotre poste n'existait pas, que se passerait-il concrètement ? » La\nplupart des réponses tournaient autour de : « Je fais le relais entre le\nhaut et le bas. » Le relais. C'est-à-dire : je prends l'information d'un\ncôté, je la reformule, et je la transmits de l'autre côté. Un traducteur\npermanent entre des étages qui, sans ces traducteurs, seraient\nobligés de se parler directement.\nClaire a supprimé trois niveaux. Pas les personnes — les niveaux. Les\nresponsables d'atelier sont devenus des « référents techniques » avec\nun rôle d'expertise, pas de commandement. Les responsables de\nproduction sont devenus des « facilitateurs » dont le rôle n'était plus\nde valider, mais de résoudre les blocages. Et les chefs d'équipe ont\nreçu une autonomie qu'ils n'avaient jamais eue : budgets d'achat\njusqu'à 500 euros sans validation, modification des plannings sans\nremonter, contact direct avec la direction quand nécessaire.\nCe qui s'est passé. Les trois premiers mois ont été chaotiques. Les\ngens ne savaient pas quoi faire de leur liberté. Certains chefs\n80",
