      "pageNumber": 82,
      "text": "d'équipe étaient paralysés : « Vous êtes sûre que j'ai le droit ? »\nD'autres ont testé les limites. Quelques erreurs ont été commises —\ndes commandes inutiles, des plannings mal pensés. Claire les a\nassumées publiquement : « C'est le prix de l'apprentissage. Ce n'est\npas le prix de l'échec. »\nAu bout de six mois, les résultats ont commencé à apparaître. Le\ndélai moyen de décision opérationnelle est passé de 8 jours à 1,5\njour. Les idées terrain implémentées sont passées de 3 par an à 47.\nLa productivité a augmenté de 25 % — non pas parce que les gens\ntravaillaient plus, mais parce qu'ils passaient moins de temps à\nattendre des autorisations, à remplir des formulaires, à reformuler\ndes demandes pour les rendre « présentables » au niveau supérieur.\nEt un effet inattendu : l'absentéisme a baissé de 30 %. Quand les\ngens sentent qu'on leur fait confiance, ils viennent travailler. C'est\naussi simple et aussi compliqué que ça.\nLe prix payé. Deux cadres intermédiaires ont quitté l'entreprise,\nincapables d'accepter un rôle sans pouvoir hiérarchique. Un syndicat\na émis des réserves sur le « transfert de charge » vers les chefs\nd'équipe. Et Claire elle-même a dû se battre avec le groupe pour\nexpliquer que « moins de managers » ne signifiait pas « moins de\nmanagement » mais « un management différent ».\nHistoire 2 : Le VP qui a rendu les salaires transparents\nLe contexte. Une entreprise technologique de 250 personnes, en Île-\nde-France. Comme dans beaucoup d'entreprises françaises, les\nsalaires étaient un tabou absolu. On pouvait parler de politique, de\nreligion, de vie privée — mais pas de combien on gagne. Ce secret\n81",
