      "pageNumber": 85,
      "text": "— c'est-à-dire 80 % des effectifs — ne recevaient rien de significatif,\nni en feedback ni en reconnaissance.\nLa personne. Isabelle, DRH, 15 ans d'expérience, fatiguée des rituels\nvides. Elle a dit un jour en réunion : « On passe 3 000 heures par an\nsur un processus qui ne rend personne meilleur. Si quelqu'un peut\nme prouver le contraire, je m'excuse et on continue. » Personne n'a\nrien prouvé.\nCe qu'elle a fait. Elle a supprimé l'entretien annuel. Totalement. Pas\n« allégé ». Supprimé. À la place, elle a mis en place un système de\nfeedback continu entre pairs — pas entre manager et managé, entre\npairs. Chaque trimestre, chaque personne demande du feedback à\ntrois collègues de son choix — pas nécessairement son manager, pas\nnécessairement quelqu'un de son équipe. Le feedback est structuré\nautour de trois questions :\n1. Qu'est-ce que cette personne fait bien et devrait continuer ?\n2. Qu'est-ce qu'elle pourrait améliorer ?\n3. De quoi a-t-elle besoin pour progresser ?\nLe feedback est visible par la personne concernée et par elle seule.\nPas par le manager. Pas par la DRH. Pas par un comité. La personne\nen fait ce qu'elle veut.\nCe qui s'est passé. Les six premiers mois, le système a été sous-\nutilisé. Les gens ne savaient pas comment donner du feedback\nconstructif — normal, personne ne leur avait jamais appris. Isabelle\na organisé des ateliers (pas des formations — des ateliers, avec des\nexercices, des mises en situation, du concret).\nPuis le système a décollé. Les gens ont commencé à solliciter du\nfeedback en dehors des cycles trimestriels. Des conversations\n84",
