      "pageNumber": 86,
      "text": "spontanées ont émergé — le genre de conversations qui n'existent\npas dans un système d'évaluation descendant. Des compétences\ncachées ont été révélées (« je ne savais pas que tu étais bon en data\nviz, tu pourrais m'aider  ?  »). Des problèmes relationnels ont été\nrésolus en amont, avant de devenir des conflits RH.\nAu bout d'un an, le taux de satisfaction interne avait augmenté de 34\npoints. Et la qualité du travail — mesurée par la satisfaction client —\navait progressé de 18 %.\nHistoire 4 : Le CEO qui a plafonné son salaire\nLe contexte. Une ETI (Entreprise de Taille Intermédiaire) de 1 200\npersonnes, secteur agroalimentaire. Le CEO gagnait 28 fois le salaire\nle plus bas de l'entreprise. Un écart « raisonnable » par les standards\ndu marché — dans le CAC 40, le ratio moyen est de 1 à 100.\nLa personne. Philippe, 56 ans, CEO depuis huit ans. Fils de\nmaraîcher, comme il aime le rappeler. Un homme qui n'a pas oublié\nd'où il vient, mais qui s'est laissé porter par un système qui\nrécompense la position plus que la contribution.\nUn jour, Philippe a vu un documentaire sur les inégalités salariales.\nRien de spécial — le genre de documentaire qu'on regarde un\ndimanche soir sans trop y penser. Mais une phrase l'a frappé : « À\npartir de quel ratio, le dirigeant cesse-t-il d'être un leader pour\ndevenir un extracteur ? »\nLe lendemain, il a demandé à la DRH le salaire le plus bas de\nl'entreprise. 1 650 euros bruts. Il a fait le calcul. Son package total\nreprésentait 46 200 euros par mois. Il a regardé le chiffre longtemps.\n85",
