      "text": "Ce qu'il a fait. Il a proposé au conseil d'administration de plafonner\nsa rémunération à 5 fois le salaire le plus bas de l'entreprise. Le\nconseil a ri. Puis a compris qu'il ne riait pas. Les discussions ont duré\ntrois mois. Des avocats ont été consultés. Des actionnaires ont été\ninformés.\nPhilippe a tenu bon. Son argument  : «  Si je ne peux pas vivre\ndignement avec 5 fois le salaire le plus bas, alors le salaire le plus bas\nn'est pas digne. Et si le salaire le plus bas n'est pas digne, c'est mon\nproblème à résoudre, pas leur précarité à accepter. »\nLe ratio a été fixé à 5. Ce qui signifiait deux choses :\n1. Le salaire de Philippe a baissé significativement.\n2. Le salaire minimum de l'entreprise a été augmenté — parce\nque Philippe avait tout intérêt, désormais, à ce que le plancher\nmonte.\nCe qui s'est passé. L'effet le plus immédiat n'a pas été économique. Il\na été symbolique. Quand les employés ont appris que leur CEO avait\nvolontairement baissé son salaire et que le leur augmentait en\nconséquence, quelque chose s'est passé. Pas de l'amour — ce serait\nnaïf. De la crédibilité. Pour la première fois, les discours sur « la\ncommunauté d'entreprise » et « la valeur de chacun » avaient un\nancrage concret. Un dirigeant avait mis son argent là où était sa\nbouche.\nEn trois ans, le taux de fidélisation est passé de 82 % à 94 %. Les\ncandidatures spontanées ont triplé. Et les résultats financiers  ?\nStables la première année. En hausse de 8 % la deuxième. En hausse\nde 14 % la troisième. Parce que les gens qui se sentent respectés ne\n86",
