      "pageNumber": 88,
      "text": "travaillent pas plus. Ils travaillent mieux. Et quand ils travaillent\nmieux, tout le monde gagne plus.\nMême Philippe, malgré le plafond. Parce que 5 fois un plancher qui\nmonte, ça finit par monter aussi.\nHistoire 5 : La Directrice d'hôpital et le modèle Buurtzorg\nLe contexte. Un centre hospitalier public, en Bretagne. 2 000 agents.\nDes couloirs qui sentent le désinfectant et la fatigue. Des infirmières\nqui courent. Des aides-soignantes qui pleurent parfois dans les\nvestiaires. Des médecins qui signent des prescriptions sans lever les\nyeux. Un taux de burnout parmi les plus élevés de la région.\nLa personne. Véronique, 52 ans, directrice adjointe en charge des\nsoins. Elle a lu un article sur Buurtzorg, ce modèle néerlandais de\nsoins à domicile qui a supprimé la hiérarchie traditionnelle pour\nlaisser les équipes d'infirmières s'auto-organiser. 15 000 infirmières,\npas de managers intermédiaires. Le meilleur taux de satisfaction\npatient et le meilleur taux de satisfaction employé du pays.\nVéronique s'est dit : « Et si on essayait ? Pas dans tout l'hôpital.\nJuste dans un service. Pour voir. »\nCe qu'elle a fait. Elle a choisi un service de médecine interne. 35\nagents. Un service « moyen » — ni le pire ni le meilleur. Elle a\nproposé une expérimentation de six mois : l'équipe organiserait elle-\nmême ses plannings, ses répartitions de tâches, ses réunions. Le\ncadre de santé resterait en poste mais dans un rôle de « coach »\nplutôt que de «  chef  ». Et l'équipe aurait un budget de\nfonctionnement qu'elle gérerait de manière autonome.\n87",
