      "text": "Le mot de la ﬁn\nSept gestes. Sept premiers pas.\nVous n'êtes pas obligé de tous les faire. Vous n'êtes pas obligé de\ncommencer par le premier. Vous n'êtes pas obligé de les faire dans\nl'ordre, ni de les faire parfaitement, ni de les faire tout de suite.\nMais faites-en un.\nUn seul.\nParce que le changement ne commence pas par un plan. Il\ncommence par un geste. Et ce geste, personne ne peut le poser à\nvotre place.\nVous êtes arrivé au dernier étage de ce livre. Ou au premier — selon\nla direction dans laquelle vous le lisez. Le bâtiment est le même. Les\nétages sont les mêmes. Mais vous, peut-être, êtes un peu différent de\nla personne qui a ouvert ce livre il y a quelques heures.\nSi c'est le cas, ce livre a fait son travail.\nLe reste, c'est le vôtre.\n« On ne change pas une organisation. On change les conversations\nqu'elle a avec elle-même. »\nLe bouclier des fonctions support — La bureaucratie comme\nanesthésique\nAu Sommet, la prolifération des fonctions support répond à un\nbesoin psychologique inconscient : se protéger du réel.\nPour un dirigeant du 7ème ou 8ème étage, affronter directement la\ncolère ou le désarroi du Terrain est insupportable. Les services\n102",
