      "pageNumber": 106,
      "text": "CE QUE VOUS NE VOYEZ PAS.\nVous êtes descendu. Étage par étage. Vous avez vu le VP qui doute de\nsa signature. Le Directeur qui découvre le terrain. Le Manager de\nManagers qui se reconnaît dans un livre. Le Manager de Proximité\nqui se souvient.\nMaintenant, il faut parler de ce que vous ne voyez pas. Pas par choix.\nPas par malveillance. Par architecture.\nLa tour est construite de telle manière que certaines choses ne\nmontent jamais. Elles restent en bas. Invisibles. Comme si elles\nn'existaient pas.\nAngle mort n° 1 : L'auto-organisation\nEn bas, les gens s'organisent. Sans vous. Sans permission. Sans\nvalidation. Ils créent des systèmes parallèles, des plannings\ninformels, des répartitions de tâches qui ne figurent dans aucun\norganigramme.\nIls le font parce que le système officiel — celui que vous avez conçu,\nvalidé, présenté en comité de direction — ne marche pas. Ou ne\nmarche plus. Ou n'a jamais vraiment marché sur le terrain.\nL'auto-organisation n'est pas une rébellion. C'est de la survie\norganisationnelle. Et elle est partout. Dans chaque service, chaque\néquipe, chaque atelier. Partout où des gens compétents font face à un\nsystème inadapté.\n105",
