      "pageNumber": 111,
      "text": "▌  VOIX DU SOMMET\n« Quand j'ai appris qu'un technicien avait développé une appli qui\nremplaçait un outil à 200 000 € du budget IT, je n'ai pas su quoi\ndire. J'étais partagé entre l'admiration et la gêne. Admiration\npour lui. Gêne pour nous. »\n— Directeur des opérations, 51 ans\n« On m'a présenté les résultats d'un \"audit social\". Tout était vert.\nSatisfaction, engagement, bien-être — tout vert. Puis j'ai croisé un\nagent dans le couloir. Il m'a dit, en passant, presque en\ns'excusant : \"La ventilation est en panne depuis avril.\" On était en\nseptembre. Cinq mois. Vert. »\n— Directrice régionale, secteur tertiaire, 46 ans\n▌  LA QUESTION\nPrenez votre dernier rapport d'activité. Celui avec les indicateurs,\nles graphiques, les couleurs.\nMaintenant demandez-vous :\nQu'est-ce qui n'y figure pas ?\nCe qui n'y figure pas — c'est ce chapitre.\n110",
