      "pageNumber": 113,
      "text": "Le coût du sens\nQuand vous étiez stagiaire, vous faisiez quelque chose. Vous\nproduisiez. Vous voyiez le résultat de votre travail. Il y avait un lien\nentre votre effort et un effet dans le monde réel.\nEt maintenant ?\nMaintenant, vous êtes en réunion. Vous réorganisez. Vous validez.\nVous arbitrez entre deux options que d'autres ont préparées. Vous\nrelisez des documents que d'autres ont écrits. Vous signez des choses\nque d'autres ont conçues.\nLa question revient, la nuit, quand la maison est silencieuse :\nÀ quoi je sers ?\nCe n'est pas une crise existentielle. C'est une question légitime. Et\nelle est posée par de plus en plus de cadres supérieurs. Pas à voix\nhaute — à voix basse, dans les cabinets de coaching, chez le psy, dans\nles questionnaires anonymes sur le bien-être au travail.\nUne étude de Deloitte (2022) révèle que 75 % des cadres dirigeants\ndéclarent ressentir un «  manque de sens  » dans leur activité\nprofessionnelle. 75 %. Trois sur quatre.\nLe coût de la santé\nLe stress chronique de l'étage supérieur est différent de celui de\nl'étage inférieur — mais il est réel.\n112",
