      "text": "▌  VOIX DU SOMMET\n« Mon fils a dit à sa maîtresse que papa \"va à des réunions\". Pas\nqu'il construit, soigne, cuisine ou répare. Qu'il va à des réunions.\nJ'ai voulu corriger. Je n'ai pas trouvé quoi dire d'autre. »\n— Directeur, 48 ans\n« J'ai fait un burnout à 43 ans. Mon médecin m'a dit : \"Vous\ntravaillez trop.\" Ce n'était pas ça. Je ne travaillais pas trop. Je\ntravaillais pour rien. Le volume n'était pas le problème. Le vide,\nsi. »\n— Ex-VP, reconverti en artisan menuisier, 47 ans\n« Ma femme m'a quitté. Dans la lettre, elle a écrit : \"Je ne sais pas\ncontre quoi je me bats. Si c'était une maîtresse, je pourrais lutter.\nMais c'est un bureau. Un tableur. Un mail à 23h. Je ne peux pas\nlutter contre ça.\" »\n— Manager de Managers, groupe de luxe, 52 ans\n▌  LA QUESTION\nLa cage est dorée. Le salaire est bon. Le titre est impressionnant.\nMais est-ce que vous dormez bien ?\nC'est la seule question qui compte.\n115",
