      "pageNumber": 119,
      "text": "la norme est le consensus mou et le statu quo confortable, celui qui\ndiverge se met en danger.\nLe système ne sélectionne pas les meilleurs leaders. Il sélectionne les\nplus conformes. Ceux qui ne font pas de vagues. Ceux qui livrent les\nrésultats attendus. Ceux qui ne remettent rien en question.\nEt ce sont ces mêmes personnes qui, une fois en place, reproduisent\nle système qui les a sélectionnées.\nRaison n° 4 : L'illusion du changement\nVous avez peut-être l'impression de changer. Vous avez lancé un\nprogramme de « transformation culturelle ». Vous avez nommé un\n« Chief Happiness Officer ». Vous avez organisé un « hackathon\ninnovation ». Vous avez commandé une enquête de satisfaction.\nCes actions ont un point commun  : elles ne changent rien à la\nstructure. Elles changent le vocabulaire, la décoration, le discours —\nmais pas la répartition du pouvoir, de l'argent et de la décision.\nC'est du changement cosmétique. Il rassure tout le monde. Il permet\nde cocher la case « transformation en cours » dans le rapport annuel.\nEt il laisse la tour exactement telle qu'elle est.\nLe vrai changement — celui qui redistribue la décision, l'autonomie\net la valeur — personne ne le propose. Parce que ce changement-là\ndérange ceux qui le proposeraient.\nRaison n° 5 : Le système sélectionne contre le\nchangement\nVoici la raison la plus profonde, et la moins personnelle.\n118",
