      "pageNumber": 123,
      "text": "Votre indicateur Système classique Buurtzorg\nCoûts par patient Base -40 %\nAbsentéisme 7-10 % < 3 %\nTurnover 15-25 % < 5 %\nSatisfaction employés Moyenne N°1 du pays\nCoût de management Significatif Quasi-nul\nLisez la colonne de droite avec vos lunettes de VP. Ce n'est pas un\nprojet social. C'est un avantage compétitif massif. -40 % de coûts.\nTurnover divisé par cinq. Satisfaction maximale.\nQuel cabinet de conseil vous promettrait ces résultats ? Aucun. Parce\nqu'ils viennent d'un modèle qui supprime le besoin de cabinets de\nconseil.\nFAVI — Plus performant, pas moins\nVous gérez une usine. Vous connaissez les problèmes  : qualité,\ndélais, absentéisme, tensions sociales.\nFAVI — fonderie picarde, 400 ouvriers, zéro contremaître — a été\nleader européen de son marché pendant 30 ans. Sans plan social.\nSans consultant. Sans lean management.\nLe modèle : des mini-usines de 20-30 personnes, autonomes, en lien\ndirect avec le client. Chaque opérateur connaît le client final. Chaque\nopérateur peut prendre des décisions.\nCe que vous gagnez :\n122",
