      "pageNumber": 131,
      "text": "La solitude du manager qui a compris\nIl y a un moment précis, dans la lecture d'un livre comme celui-ci, où\nquelque chose bascule. Un manager lit un chapitre sur l'autonomie\ndes équipes, sur les SCOP, sur Buurtzorg — et une petite voix\nintérieure dit : ils ont raison. Les réunions sont inutiles. Le reporting\nest du théâtre. Les entretiens annuels sont une farce. La hiérarchie à\nsept niveaux est une absurdité.\nEt puis la même voix ajoute : mais je ne peux rien y faire.\nVous êtes peut-être dans cette situation en ce moment. Vous êtes\nseul(e) avec cette conviction naissante, entouré(e) de collègues-\nmanagers qui n'ont pas lu ce livre, d'un DRH qui parle «  talent\nmanagement  » sans y croire, et d'un COMEX qui considère que\nl'innovation organisationnelle, c'est mettre un baby-foot dans la salle\nde pause.\nCette solitude est réelle. Ne la sous-estimez pas. Et ne la laissez pas\nvous paralyser.\nLa première chose à accepter\nVous ne changerez pas l'entreprise. Pas lundi. Pas cette année. Peut-\nêtre jamais.\nCe que vous pouvez changer, c'est votre cercle. Votre équipe. Votre\npérimètre. Les quinze, trente, cinquante personnes qui dépendent de\nvous. C'est déjà énorme. C'est déjà un monde.\nUn directeur d'usine qui transforme son site ne transforme pas le\ngroupe de 40 000 salariés. Mais il transforme la vie quotidienne de\n200 personnes. Et si ça marche, d'autres directeurs regardent. Et\n130",
