      "text": "LE SAVIEZ-VOUS ?\nUne étude menée par l'Université de Birmingham en 2017 sur 20\n000 salariés a montré que les travailleurs disposant d'une\nautonomie dans la prise de décision rapportent des niveaux de\nsatisfaction et de bien-être significativement supérieurs — et leurs\nperformances sont, en moyenne, 20 % plus élevées que celles de\nleurs collègues soumis à un management directif. L'autonomie\nn'est pas un cadeau qu'on fait aux salariés. C'est un\ninvestissement qui rapporte.\n3. Ce qui NÉCESSITE l'accord d'en haut (et comment\nl'obtenir)\nCertains changements dépassent votre mandat. Vous ne pouvez pas\nles faire seul(e). Mais vous pouvez les proposer — à condition de\nparler le bon langage.\nSupprimer un niveau hiérarchique\nC'est l'un des gestes les plus puissants — et les plus risqués. Vous\nproposez de supprimer une couche de management dans votre\npérimètre. Ce qui signifie souvent : supprimer un poste (parfois le\nvôtre, parfois celui d'un adjoint, d'un chef d'équipe).\nVous ne pouvez pas faire ça seul(e). Vous avez besoin de votre N+1 et\ndes RH. Probablement du DAF aussi, pour les implications\nbudgétaires.\nComment le pitcher :\nNe dites jamais « on devrait supprimer ce poste ». Dites :\n138",
