      "pageNumber": 141,
      "text": "Changer le système de rémunération\nVous ne pouvez pas toucher aux grilles salariales. C'est le domaine\ndes RH, des conventions collectives, parfois du droit du travail. Mais\nà l'intérieur de votre périmètre d'influence, vous pouvez faire bouger\nles lignes.\nCe que vous pouvez porter comme proposition :\nLa transparence salariale. Poussez les RH à publier les\nfourchettes de rémunération par poste. Pas les salaires\nindividuels (pas encore), mais les fourchettes. C'est la loi dans\ncertains pays. Ça le sera bientôt en France (directive\neuropéenne 2023). Autant anticiper.\nLes primes collectives plutôt qu'individuelles. Proposez que le\nbonus annuel soit calculé sur la performance de l'équipe, pas\nsur celle de chaque individu. L'argument  : les primes\nindividuelles créent de la compétition interne. La compétition\ninterne détruit la coopération. La coopération est ce qui\nproduit les résultats. CQFD.\nL'évaluation par les pairs. Proposez qu'une partie de\nl'évaluation annuelle (disons 30 %) soit fondée sur le retour\ndes collègues, pas uniquement sur l'avis du manager. C'est un\nlevier puissant  : ça redistribue le pouvoir d'évaluation, ça\nréduit le biais du manager unique, et ça force les gens à se\npréoccuper de leur impact sur les autres, pas seulement de\nleur relation avec le chef.\nLe cadrage stratégique : présentez tout cela comme une stratégie de\nrétention des talents. Les jeunes générations quittent les entreprises\nqu'elles perçoivent comme injustes. Et «  injuste  », dans leur\n140",
