      "text": "faire et qui, curieusement, a les meilleurs résultats. C'est elle votre\npilote.\nÉtape 2 : Définissez concrètement le périmètre d'autonomie.\nL'autonomie totale n'existe pas et n'est pas souhaitable au\ndémarrage. Soyez explicite :\nL'équipe décide : planning des congés, répartition des tâches,\nméthodes de travail, choix des outils, budget opérationnel\n(dans une enveloppe définie).\nLe manager décide encore  : recrutement (pour l'instant),\nbudget d'investissement, relations avec les autres services,\narbitrages stratégiques.\nLa frontière est claire. Elle évoluera avec le temps — mais au départ,\ntout le monde a besoin de savoir où elle est.\nÉtape 3 : Posez des métriques et des points de revue.\nUn pilote sans mesure n'est pas un pilote — c'est un caprice.\nDéfinissez ce que vous mesurez (productivité, qualité, satisfaction\nclient, absentéisme, turnover) et quand vous faites le point (3 mois, 6\nmois). Proposez ces métriques à votre direction avant de lancer le\npilote. Ça les rassure. Et ça vous protège : si les résultats sont bons,\npersonne ne pourra dire « oui mais c'est anecdotique ».\n142",
