      "pageNumber": 145,
      "text": "Des objectifs clairs (pas des tâches — des objectifs)\nDes ressources (budget, outils, temps)\nDe l'information (contexte stratégique, données marché,\nretour client)\nUn filet de sécurité : quelqu'un vers qui escalader quand le\nproblème dépasse leur périmètre\nÊtre facilitateur, ce n'est pas être absent. C'est être présent\ndifféremment.\nVOIX DU SOMMET\n« J'ai fait cette erreur. J'ai lu Laloux, j'ai lu Semler, j'ai lu Isaac\nGetz, et le lundi matin j'ai dit à mon équipe : \"À partir de\nmaintenant, c'est vous qui décidez.\" Ils m'ont regardé comme des\nbiches dans les phares. Personne n'a rien décidé pendant trois\nsemaines. Le chaos s'est installé. C'est mon adjoint qui m'a remis\nles pieds sur terre : \"Ils ne savent pas décider. Ils n'ont jamais\nappris. Il faut les accompagner, pas les larguer.\" Il avait raison.\nJ'ai repris une posture de guide — présent, disponible, mais sans\ndécider à leur place. Ça a pris deux mois. »\n— Chef de département, collectivité territoriale, Occitanie\nLe piège du copier-coller\nVous avez lu le chapitre sur Buurtzorg. Des équipes de 12\ninfirmières, sans manager, qui s'organisent seules. Résultats\nextraordinaires. Vous voulez faire pareil.\nNe faites pas pareil.\n144",
