      "text": "exécuter, pas à penser. Et vous arrivez un beau matin en disant :\n« Maintenant, pensez. »\nLes premières semaines d'autonomie sont inconfortables. Pour tout\nle monde. Les gens vont :\nVous demander des instructions (par habitude)\nSe sentir perdus sans structure (c'est normal)\nPrendre des décisions médiocres (c'est le prix de\nl'apprentissage)\nSe plaindre qu'on ne les « manage » plus (ce qui signifie en\nréalité : « je ne sais pas encore fonctionner autrement »)\nC'est normal. Restez le cap. Ça s'améliore vers le troisième mois.\nVers le sixième mois, les mêmes personnes qui demandaient des\ninstructions refuseront qu'on leur en donne.\nLe piège du retour en arrière\nAu premier problème — un client mécontent, un livrable en retard,\nun conflit interne — votre instinct reptilien va hurler : reprends le\ncontrôle. C'est un réflexe. Celui du pompier qui, face au feu, court\nvers les flammes. Sauf que, dans ce cas, reprendre le contrôle, c'est\nl'équivalent de remettre le feu.\nRésistez.\nLes problèmes pendant la transition sont normaux. Ce ne sont pas la\npreuve que l'autonomie ne marche pas. Posez-vous une seule\nquestion  : «  Est-ce qu'il y avait des problèmes AVANT le\nchangement ? »\n146",
