      "pageNumber": 148,
      "text": "La réponse est oui. Toujours oui. Il y avait des clients mécontents,\ndes retards, des conflits. La seule différence, c'est que dans l'ancien\nsystème, vous ne les voyiez pas — parce que votre équipe les cachait,\nles gérait en silence, ou les subissait sans broncher. L'autonomie ne\ncrée pas les problèmes. Elle les rend visibles. Et c'est une bonne\nnouvelle, même si ça n'en a pas l'air.\nLA QUESTION\nLa prochaine fois qu'un problème surgira dans votre équipe,\navant de reprendre la main, demandez : « Qu'est-ce que l'équipe\npropose comme solution ? » Vous pourriez être surpris(e).\n5. Le langage — comment parler de changement dans\nla tour\nVous ne pouvez pas utiliser le vocabulaire de ce livre en comité de\ndirection. Si vous dites « il faut faire confiance aux gens » dans une\nsalle où le mot « confiance » n'existe qu'adossé au mot « client »\n(« relation de confiance client »), vous allez passer pour un naïf. Ou\npire : pour un danger.\nIl faut apprendre la traduction simultanée. Penser dans un langage,\nparler dans un autre. C'est épuisant. C'est nécessaire.\n147",
