      "pageNumber": 153,
      "text": "LE SAVIEZ-VOUS ?\nDans plusieurs SCOP (Sociétés Coopératives et Participatives)\nfrançaises, le syndicat n'est pas l'adversaire de la direction — il\nest une partie de la gouvernance. Chez Chèque Déjeuner (devenu\nUp Group), coopérative de 3 500 salariés, les représentants du\npersonnel siègent au conseil de surveillance et participent\ndirectement aux décisions stratégiques. Résultat : un taux de\nconflictualité sociale parmi les plus bas du secteur, et un taux\nd'engagement parmi les plus hauts.\nVOIX DU SOMMET\n« Ma plus grosse erreur a été de ne pas parler aux délégués\nsyndicaux avant de lancer le projet. Je me suis dit : \"c'est un\nprojet managérial, ça ne les regarde pas.\" Trois semaines plus\ntard, j'avais un préavis de grève sur le bureau. Pas parce qu'ils\nétaient contre le fond — au contraire, quand j'ai finalement pris le\ntemps de leur expliquer, ils ont dit : \"C'est ce qu'on demande\ndepuis dix ans.\" Mais ils étaient furieux de ne pas avoir été\nconsultés. Leur message était clair : \"Ne faites pas pour nous sans\nnous.\" Leçon apprise. »\n— Directeur d'usine, secteur automobile, Hauts-de-France\n7. Le coût financier de la transition\nSoyons honnêtes. La transition a un coût. Prétendre le contraire\nserait malhonnête — et vous perdriez toute crédibilité face à un DAF\nou un contrôleur de gestion.\n152",
