      "text": "Résultat : Baisse spectaculaire du turnover, alignement des\nintérêts, et valorisation durable de l'entreprise.\n2. Le comité de gouvernance paritaire à veto opérationnel\nAccorder aux représentants du Terrain (élus par leurs pairs,\npas nommés par la direction) un droit de veto sur les décisions\nqui touchent directement leurs conditions de travail et la\nqualité du produit.\nRésultat  : Fin des projets de restructuration absurdes\nimaginés en chambre close.\n3. La subsidiarité inscrite dans le pacte d'actionnaires\nInscrire dans les statuts que toute décision qui peut être prise\nau niveau local DOIT être prise au niveau local, le siège\nn'intervenant qu'en dernier recours..\n164",
