      "pageNumber": 168,
      "text": "Il n'y a plus de Terrain. Il n'y a plus de Sommet.\nIl n'y a que nous.\n▌  LE MIROIR CROISÉ — CE QUE LE SOMMET RÉPOND AU\nTERRAIN\n1. Sur la peur : « Quand les marchés tremblent et que les investisseurs\nexigent 10 % de coupe budgétaire, savez-vous que ma plus grande\nhantise est d'avoir à fermer un site entier ? »\n2. Sur la solitude : « Réalisez-vous que plus on monte dans cette tour, plus\npersonne ne nous dit la vérité, et que chaque sourire qu'on me fait est ﬁltré\npar la peur ou l'intérêt ? »\n3. Sur le système : « Je ne contrôle pas les règles du jeu autant que vous\nle croyez. Je suis moi aussi le prisonnier d'un système qui exige toujours\nplus avec toujours moins. »\n4. La réponse centrale : « Si vous m'enleviez mon titre aujourd'hui,\nj'aimerais qu'on se retrouve autour d'une vraie table, sans ﬁltre ni\nhiérarchie, pour réapprendre à construire ensemble. »\nVous êtes arrivé au cœur du livre.\nPour découvrir la tour à travers le regard du sol et la réalité du\ntravail concret, retournez l'ouvrage et entamez votre lecture\ndepuis la seconde couverture.\n167",
